/// PR #1265 follow-up — the slides session `mofa_*` allowlist filter
/// MUST run on the WS turn path (`run_standalone_turn` in
/// `handle_turn_start`), not only on the gateway `SessionActor`
/// path. The bug: round-12 fleet slides validator v2 (2026-05-25)
/// observed both `bot` and `crew` invoking `mofa_list_styles` on
/// the web dashboard's slides topic, proving the
/// `keep_tool_in_slides_session` retain was a no-op on the WS
/// path. The fix wires the same `is_slides_session + activate +
/// retain` pattern from `session_actor.rs:2947-2965` into the
/// per-turn registry build at the WS handler. This test reproduces
/// the registry shape the WS handler builds AND drives the
/// `topic.starts_with("slides")` detection from a real
/// `SessionKey`, so a regression that re-deletes the wiring (or
/// breaks the topic predicate) WOULD flip this test red.
#[test]
fn slides_topic_retain_evicts_sibling_mofa_tools_on_ws_turn_path() {
    use async_trait::async_trait;
    use eyre::Result;
    use octos_agent::tools::{Tool, ToolResult};
    use serde_json::Value;

    struct NameOnlyTool(&'static str);

    #[async_trait]
    impl Tool for NameOnlyTool {
        fn name(&self) -> &str {
            self.0
        }
        fn description(&self) -> &str {
            "stub"
        }
        fn input_schema(&self) -> Value {
            json!({})
        }
        async fn execute(&self, _args: &Value) -> Result<ToolResult> {
            Ok(ToolResult::default())
        }
    }

    let temp = tempfile::tempdir().expect("tempdir");
    let mut registry = octos_agent::ToolRegistry::with_builtins(temp.path());

    // Register the full `mofa_*` plugin surface a fleet host
    // typically loads from the `mofa-slides` and sibling skill
    // manifests. The retain must hide every entry except
    // `mofa_slides`. We register the tools directly (rather than
    // going through `defer_group("group:media") + activate(...)`)
    // because the test cares about the post-retain registry
    // contents, not the defer/activate plumbing — which is already
    // covered by `tools::policy::tests` in `octos-agent`.
    for name in [
        "mofa_slides",
        "mofa_list_styles",
        "mofa_site",
        "mofa_youtube",
        "mofa_publish",
        "mofa_research",
        "mofa_pdf",
        "mofa_xlsx",
        "mofa_cli",
        "mofa_fm",
        "mofa_frame",
        "mofa_podcast",
        "mofa_infographic",
        "mofa_cards",
        "mofa_comic",
    ] {
        registry.register(NameOnlyTool(name));
    }
    // Also register a non-`mofa_*` tool so the test pins that the
    // retain does NOT widen its eviction beyond the prefix.
    registry.register(NameOnlyTool("send_file"));

    // Drive the production gate from a real SessionKey — this is
    // the same shape the WS handler observes via `params.session_id`.
    let session_id = SessionKey("web:tester#slides round12-quasars".to_owned());
    let is_slides_session = session_id
        .topic()
        .is_some_and(|topic| topic.starts_with("slides"));
    assert!(
        is_slides_session,
        "topic predicate must match the gateway path's \
             `session_key.topic().is_some_and(|t| t.starts_with(\"slides\"))`",
    );
    // Mirror the production wiring at `run_standalone_turn`. RFC-0
    // (#1289): no `activate("group:media")` — deferral was removed.
    registry.retain(octos_agent::keep_tool_in_slides_session);

    // `mofa_slides` survives — it is the canonical slides skill.
    assert!(
        registry.get("mofa_slides").is_some(),
        "mofa_slides must survive the slides-session retain",
    );
    // Every other `mofa_*` skill is evicted. The full list mirrors
    // `tools::policy::tests::should_drop_sibling_mofa_skills_in_slides_session`
    // — keep the two lists in lockstep so a future widening of the
    // retain (e.g. adding `mofa_list_styles` back) catches BOTH
    // tests.
    for evicted in [
        "mofa_list_styles",
        "mofa_site",
        "mofa_youtube",
        "mofa_publish",
        "mofa_research",
        "mofa_pdf",
        "mofa_xlsx",
        "mofa_cli",
        "mofa_fm",
        "mofa_frame",
        "mofa_podcast",
        "mofa_infographic",
        "mofa_cards",
        "mofa_comic",
    ] {
        assert!(
            registry.get(evicted).is_none(),
            "{evicted} must be evicted from the per-turn registry \
                 on a slides session (round-12 v2 fleet validator caught \
                 the LLM invoking it instead of `glob(\"styles/*.toml\")` \
                 per `prompts/slides_default.txt`)",
        );
    }
    // Non-`mofa_*` tools are untouched.
    assert!(
        registry.get("send_file").is_some(),
        "send_file (and other non-`mofa_*` tools) must remain \
             available — the retain only targets the `mofa_*` prefix",
    );
}

/// Companion to `slides_topic_retain_evicts_sibling_mofa_tools_on_ws_turn_path`:
/// pin that a NON-slides session topic does NOT trigger the retain.
/// A bug that drops the `is_slides_session` guard would silently
/// hide every `mofa_*` tool on every session — flips this test red.
#[test]
fn non_slides_topic_leaves_mofa_tools_visible_on_ws_turn_path() {
    use async_trait::async_trait;
    use eyre::Result;
    use octos_agent::tools::{Tool, ToolResult};
    use serde_json::Value;

    struct NameOnlyTool(&'static str);

    #[async_trait]
    impl Tool for NameOnlyTool {
        fn name(&self) -> &str {
            self.0
        }
        fn description(&self) -> &str {
            "stub"
        }
        fn input_schema(&self) -> Value {
            json!({})
        }
        async fn execute(&self, _args: &Value) -> Result<ToolResult> {
            Ok(ToolResult::default())
        }
    }

    let temp = tempfile::tempdir().expect("tempdir");
    let mut registry = octos_agent::ToolRegistry::with_builtins(temp.path());
    for name in ["mofa_slides", "mofa_list_styles", "mofa_site"] {
        registry.register(NameOnlyTool(name));
    }

    // Three topic shapes the production code must NOT treat as slides.
    for topic in ["site demo", "news daily-2026-05-25", "general chat"] {
        let session_id = SessionKey(format!("web:tester#{topic}"));
        let is_slides_session = session_id.topic().is_some_and(|t| t.starts_with("slides"));
        assert!(
            !is_slides_session,
            "topic `{topic}` must not match the slides predicate",
        );
    }

    // Even a bare session (no `#topic`) must not match.
    let bare = SessionKey("web:tester".to_owned());
    let bare_is_slides = bare.topic().is_some_and(|t| t.starts_with("slides"));
    assert!(
        !bare_is_slides,
        "a bare session (no topic) must never match the slides predicate",
    );

    // Sanity-check: every `mofa_*` is still registered because no
    // retain ran. (We don't actually call `retain` in this branch —
    // the production code is gated on `is_slides_session`.)
    for name in ["mofa_slides", "mofa_list_styles", "mofa_site"] {
        assert!(
            registry.get(name).is_some(),
            "{name} must be visible on non-slides session topics",
        );
    }
}

/// Regression: the WS turn handler (`run_standalone_turn`) MUST
/// register the per-turn `TaskSupervisor` with
/// `SessionTaskQueryStore` so `session/tasks.list` and
/// `session/status.get` can locate live spawn_only tasks after the
/// SPA closes + reopens a chat tab mid-flight.
///
/// The bug (triaged in `/tmp/task-tracker-reload-triage.md`): the
/// WS path called `session_runtime.tools.snapshot_excluding(&[])`,
/// which spins up a fresh `Arc::new(TaskSupervisor::new())` at
/// `registry.rs:829`, but never registered it with
/// `SessionTaskQueryStore` the way the gateway path does at
/// `session_actor.rs:2668-2669`. Result: `query_json(session_key)`
/// returned `[]` on reopen, the session-task tracker rendered
/// empty, and the runtime tore down its `watchSession` subscriber
/// when `has_bg_tasks=false`.
///
/// This test pins the registration sequence used by the WS path:
///   1. `snapshot_excluding(&[])` produces a registry with a fresh
///      supervisor (and `session_key: None`).
///   2. `set_session_key(session_id.to_string())` stamps the
///      registry so `spawn::register_with_lineage` writes
///      `session_key = Some(...)` onto each tracked task.
///   3. `store.register(&session_id, &supervisor, &data_dir)` makes
///      the supervisor reachable via the
///      `SessionTaskQueryStore::query_json` walk.
///
/// After those three steps a task registered through
/// `register_with_lineage(..., Some(session_key))` is reachable via
/// `query_json(session_key)` — and a regression that re-deletes
/// either step would flip this test red.
#[test]
fn ws_turn_handler_registers_supervisor_with_task_query_store() {
    let session_id = SessionKey("web:tester#turn-track-reopen".to_owned());
    let temp = tempfile::tempdir().expect("tempdir");

    // Mirror the WS path: build a parent registry the same way
    // SessionRuntime does, then snapshot it for the per-turn slot.
    let parent = octos_agent::ToolRegistry::with_builtins(temp.path());
    let mut tool_registry = parent.snapshot_excluding(&[]);

    // Step 1: stamp the per-turn snapshot with the session key so
    // tasks registered through it inherit `session_key:
    // Some(<key>)`. Without this, the
    // `TaskSupervisor::get_tasks_for_session` filter at
    // `task_supervisor.rs:2237` drops every task.
    tool_registry.set_session_key(session_id.to_string());

    // Step 2: extract the per-turn supervisor and register it in
    // the store, mirroring `session_actor.rs:2668-2669`. This is
    // the line the WS turn handler was missing.
    let task_supervisor = tool_registry.supervisor();
    let store = crate::session_actor::SessionTaskQueryStore::default();
    store.register(&session_id, &task_supervisor, temp.path());

    // Before any spawn_only task fires, the supervisor exists but
    // owns no tasks — `query_json` returns an empty array (NOT
    // missing — that would mean the supervisor wasn't registered).
    let empty = store.query_json(&session_id.to_string());
    assert_eq!(
        empty,
        serde_json::Value::Array(vec![]),
        "registered-but-empty supervisor must return [] (not absent)",
    );

    // Step 3: simulate a spawn_only task registering through
    // `register_with_lineage` with `session_key = Some(...)`. This
    // is what `spawn::Inner::execute_background` does at
    // `spawn.rs:2668-2675`.
    let task_id = task_supervisor.register_with_lineage(
        "podcast_generate",
        "call-track-track",
        Some(&session_id.0),
        None,
    );
    task_supervisor.mark_running(&task_id);

    // Now `query_json` MUST surface the live task. The pre-fix
    // behaviour was either `[]` (no supervisor registered) OR a
    // panic on stale-Weak prune; the fix turns this into a
    // single-element array carrying the running task.
    let result = store.query_json(&session_id.to_string());
    let tasks = result
        .as_array()
        .expect("query_json must produce an array even when empty");
    assert_eq!(
        tasks.len(),
        1,
        "WS-path registration must make spawn_only tasks visible via \
             SessionTaskQueryStore::query_json — got: {result}",
    );
    assert_eq!(tasks[0]["id"], task_id);
    assert_eq!(tasks[0]["tool_name"], "podcast_generate");
    assert_eq!(tasks[0]["status"], "running");
}

/// PR #1324 follow-up — pin that wiring `set_on_failure_signal` on a
/// per-turn `TaskSupervisor` (the way `run_standalone_turn` does
/// after this fix) routes a `SpawnOnlyFailureSignal` through to the
/// global master continuation queue. Pre-fix, the WS path created a
/// fresh `Arc::new(TaskSupervisor::new())` via
/// `snapshot_excluding(&[])` whose `on_failure` slot was `None` —
/// `invoke_failure_callback` silently no-op'd and the LLM never saw
/// the post-spawn failure → never retried.
///
/// The test drives the canonical post-ack failure path:
///   1. `register_with_input_and_cmid` + `mark_synth_ack_emitted`
///      mirrors what `execution.rs::spawn_only` does when the LLM
///      sees the synthetic ack tool result.
///   2. `mark_failed` fires `notify_failure`. With a non-empty
///      `tool_call_id` AND ack already recorded, the
///      `notify_failure` path calls `invoke_failure_callback`
///      synchronously inside `mark_failed`.
///   3. The callback wired here mirrors the production wiring at
///      `run_standalone_turn`: it enqueues a
///      `MasterContinuationReason::External("spawn_only_failure")`
///      continuation against the `default_agent_orchestrator()`.
///   4. The pending continuation count + prompt body are asserted.
#[tokio::test(flavor = "current_thread")]
async fn ws_turn_supervisor_routes_spawn_only_failure_to_master_continuation_queue() {
    // Use a profile_id distinct from MAIN_PROFILE_ID so this test
    // does not contaminate sibling tests that drive the
    // `default_agent_orchestrator()` static under the main profile
    // (e.g. `appui_due_fixed_loop_tick_drains_internal_continuation_turn`).
    // The drain path filters by profile, so queueing under a
    // unique profile keeps the queue local to this test.
    //
    // We do NOT call `clear_default_agent_orchestrator_for_test()`
    // at start either — it wipes the entire process-wide
    // orchestrator, including state created by sibling tests
    // running in parallel under their own profiles. The
    // session-scoped assertions below filter by our unique
    // session_id + profile_id, so prior state on other keys is
    // invisible.
    let session_id = SessionKey("web:tester#l3-recovery".to_owned());
    let profile_id = "test-l3-recovery-isolate".to_owned();
    let temp = tempfile::tempdir().expect("tempdir");

    // Mirror the WS path: per-turn registry built from snapshot.
    let parent = octos_agent::ToolRegistry::with_builtins(temp.path());
    let mut tool_registry = parent.snapshot_excluding(&[]);
    tool_registry.set_session_key(session_id.to_string());
    let task_supervisor = tool_registry.supervisor();

    // Wire `set_on_failure_signal` exactly the way
    // `run_standalone_turn` does after the PR #1324 follow-up. The
    // callback is invoked inline from `mark_failed` /
    // `notify_failure`, so a synchronous enqueue against the
    // process-wide orchestrator singleton is observable on the next
    // `pending_continuation_count_for_test()` read.
    let cb_session = session_id.clone();
    let cb_profile = profile_id.clone();
    task_supervisor.set_on_failure_signal(move |signal| {
        let _ = default_agent_orchestrator().enqueue_spawn_only_failure_continuation(
            &cb_session,
            &cb_profile,
            signal,
        );
    });

    // Background spawn_only task: register + mark synth-ack + run +
    // fail. This is the canonical production sequence in
    // `execution.rs::spawn_only` for a task that succeeds at
    // dispatch but fails AFTER the LLM has already moved on
    // (e.g. mofa_slides plugin process crashes mid-render).
    let task_id = task_supervisor.register_with_input_and_cmid(
        "mofa_slides",
        "call-l3-recovery",
        Some(&session_id.0),
        Some(serde_json::json!({"topic": "rust"})),
        Some("user-cmid-42".to_owned()),
    );
    task_supervisor.mark_synth_ack_emitted("call-l3-recovery");
    task_supervisor.mark_running(&task_id);
    task_supervisor.mark_failed(
        &task_id,
        "puer-woodblock-style: plugin exited 137 (sigkill)".to_string(),
    );

    // The callback should have enqueued exactly one external
    // spawn_only_failure continuation against the global
    // orchestrator.
    assert_eq!(
        default_agent_orchestrator()
            .pending_continuation_count_for_session_for_test(&session_id, &profile_id,),
        1,
        "WS-path failure signal must reach the master continuation queue",
    );

    // The prompt body MUST surface the tool name + error message so
    // the LLM has actionable context. We assert the structural
    // pieces (the exact wording is owned by
    // `render_spawn_only_failure_recovery_prompt` and tested
    // separately at unit scope).
    let drained = default_agent_orchestrator().drain_ready_continuations_for_session(
        &session_id,
        &profile_id,
        crate::autonomy::master_continuation_scheduler::MasterContinuationRuntimeState::idle(),
        1,
    );
    assert_eq!(drained.len(), 1, "exactly one continuation must drain");
    let prompt = master_continuation_prompt(&drained[0]);
    assert!(
        prompt.contains("[system-internal]") && prompt.contains("mofa_slides"),
        "recovery prompt must mark itself system-internal and surface \
             the failing tool name; got: {prompt}",
    );
    assert!(
        prompt.contains("puer-woodblock-style"),
        "recovery prompt must surface the underlying error so the \
             LLM can pick an alternative; got: {prompt}",
    );

    // The per-turn registry's supervisor holds an `Arc` clone the
    // failure callback captures; drop the registry to release the
    // callback before the test function returns. We deliberately
    // do NOT call `clear_default_agent_orchestrator_for_test()`
    // at end — that would wipe queue entries created by sibling
    // tests running in parallel under the shared static.
    drop(tool_registry);
}

/// #436 — serve `peer_send_input` round-trip through the master continuation
/// queue. A `peer-<slug>` session records its wire key on `session/open`; the
/// tool resolves the slug to that key and enqueues the injected text as an
/// `External(peer_send_input)` continuation which drains FOR the peer session
/// and renders VERBATIM as the peer's next user turn (no `[system-internal]`
/// envelope). Dedupe collapses an identical re-injection so the same input is
/// never delivered twice; a distinct message enqueues a fresh turn.
#[tokio::test]
async fn peer_send_input_injects_continuation_for_peer_session() {
    // Unique profile/session so the shared process-global orchestrator + peer
    // wire registry never collide with sibling tests running in parallel.
    let profile_id = "test-peer-send-input-roundtrip";
    let slug = "harbor-otter";
    // The peer's WIRE key: profiled, topic `peer-<slug>` — exactly what
    // `session/open` records and what the queue / tick / drain key on.
    let peer_key =
        SessionKey::with_profile_topic(profile_id, "api", "tab-9", &format!("peer-{slug}"));

    // `session/open` glue: registering the peer makes its slug resolvable to
    // the wire key the master's `peer_send_input` (which cannot know the
    // client-chosen wire id) must enqueue under. An empty state has no profile
    // runtime, so the close-marker retarget skip is a no-op here.
    let state = Arc::new(AppState::empty_for_tests());
    register_peer_wire_session(&state, &peer_key);
    let resolved = peer_wire_registry()
        .resolve(&peer_wire_key(profile_id, slug))
        .expect("an opened peer session's slug resolves to its wire key");
    assert_eq!(
        resolved, peer_key,
        "resolved wire key must match the opened peer session",
    );
    // A non-peer session is a no-op (never registered).
    register_peer_wire_session(&state, &SessionKey::with_profile("other", "web", "plain"));

    use crate::autonomy::agent_orchestrator::PeerSendInputEnqueueOutcome;
    let orchestrator = default_agent_orchestrator();
    let message = "focus on the auth module next; skip the CSS pass";
    // `call-1` stands in for the LLM `tool_call_id` of the first tool call.
    let outcome = orchestrator
        .enqueue_peer_send_input_continuation(&resolved, profile_id, slug, "call-1", message);
    assert_eq!(
        outcome,
        PeerSendInputEnqueueOutcome::Queued,
        "first injection must enqueue"
    );
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&peer_key, profile_id),
        1,
        "the injection is queued for the peer session",
    );

    // #436 P1 #4 — dedupe keys on the occurrence id, NOT the text: a genuine
    // retry of the SAME call (same occurrence) collapses...
    let dup = orchestrator
        .enqueue_peer_send_input_continuation(&resolved, profile_id, slug, "call-1", message);
    assert_eq!(
        dup,
        PeerSendInputEnqueueOutcome::Duplicate,
        "same-call retry must dedupe"
    );
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&peer_key, profile_id),
        1,
        "a retry must not grow the queue",
    );
    // ...while a DISTINCT call (new occurrence) with IDENTICAL text is a
    // separate injection and enqueues a second turn.
    let distinct = orchestrator
        .enqueue_peer_send_input_continuation(&resolved, profile_id, slug, "call-2", message);
    assert_eq!(
        distinct,
        PeerSendInputEnqueueOutcome::Queued,
        "a distinct tool call with identical text must NOT collapse"
    );
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&peer_key, profile_id),
        2,
        "two distinct injections must yield two turns",
    );

    // Drain (what the peer's tick does) + render (what `run_standalone_turn`
    // feeds the agent): the prompt IS the injected text, verbatim, so the peer
    // processes it as a user turn.
    let drained = orchestrator.drain_ready_continuations_for_session(
        &peer_key,
        profile_id,
        crate::autonomy::master_continuation_scheduler::MasterContinuationRuntimeState::idle(),
        1,
    );
    assert_eq!(
        drained.len(),
        1,
        "the peer session drains its injected continuation",
    );
    let prompt = master_continuation_prompt(&drained[0]);
    assert_eq!(
        prompt, message,
        "the injected text is delivered verbatim as the peer's user turn",
    );
    assert!(
        !prompt.contains("[system-internal]"),
        "a user injection must not be wrapped as a system-internal continuation",
    );

    // Housekeeping: drain the residual so the shared static is left clean for
    // sibling tests (never `clear_default_agent_orchestrator_for_test` — that
    // would wipe parallel tests' queues).
    let _ = orchestrator.drain_ready_continuations_for_session(
        &peer_key,
        profile_id,
        crate::autonomy::master_continuation_scheduler::MasterContinuationRuntimeState::idle(),
        8,
    );
}

/// #436 P1 #6 — only the peer's recorded ORIGINATOR may inject. A different
/// same-profile session (or a peer with no recorded owner) is rejected.
#[test]
fn peer_send_input_authorized_only_for_recorded_originator() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let slug = "auth-peer";
    std::fs::create_dir_all(peers_root.join(slug)).unwrap();
    std::fs::write(peers_root.join(slug).join("brief.md"), "brief").unwrap();
    let owner = "tenant-a:api:master-1";
    std::fs::write(peers_root.join(slug).join("originator"), owner).unwrap();

    // The recorded originator is authorized (trailing newline tolerated).
    assert!(peer_send_input_authorized(peers_root, slug, owner).is_ok());
    std::fs::write(
        peers_root.join(slug).join("originator"),
        format!("{owner}\n"),
    )
    .unwrap();
    assert!(peer_send_input_authorized(peers_root, slug, owner).is_ok());

    // A DIFFERENT same-profile session is rejected with the ownership error.
    let err = peer_send_input_authorized(peers_root, slug, "tenant-a:api:intruder-2")
        .expect_err("a non-originator session must be rejected");
    assert!(err.contains("not the owner"), "reason: {err}");

    // A STAGED peer (brief present) with NO recorded originator is fail-closed.
    let no_owner = "no-owner-peer";
    std::fs::create_dir_all(peers_root.join(no_owner)).unwrap();
    std::fs::write(peers_root.join(no_owner).join("brief.md"), "brief").unwrap();
    let err2 = peer_send_input_authorized(peers_root, no_owner, owner)
        .expect_err("missing originator must be unauthorized");
    assert!(err2.contains("no recorded owner"), "reason: {err2}");

    // A non-staged slug (no dir / no brief.md) is refused before any read.
    let err3 = peer_send_input_authorized(peers_root, "unstaged", owner)
        .expect_err("a non-staged peer must be unauthorized");
    assert!(err3.contains("not a staged peer"), "reason: {err3}");
}

/// Peer-fleet auto-synthesis fire policy — EXACTLY ONCE PER ROUND, on the pure
/// decision. FIRES when every owned peer is done + the master is idle + at least
/// one peer has a round past its recorded mark; HOLDS while any peer is mid-turn
/// (or has queued input), while the master is busy, when a peer has no result,
/// and when every peer's delivered round has already been summarized. A cleared
/// fleet (zero owned peers) yields ClearStamp when a stamp exists (tidy-up), else
/// Hold.
///
/// #2024 changed the exactly-once unit from FLEET to ROUND: the old gate keyed
/// on stamp existence alone, so a fleet that did more work after being
/// summarized could never synthesize again until every peer was closed. The
/// re-arm behaviour is covered by
/// `a_new_peer_round_re_arms_fleet_synthesis`.
#[test]
fn evaluate_peer_fleet_synthesis_fires_once_and_resets_on_clear() {
    use FleetSynthesisDecision::{ClearStamp, Fire, Hold};
    // A peer on round 1 with nothing summarized yet — the shape every
    // assertion below except the exactly-once one uses.
    let peer = |has_result: bool, mid_turn: bool| OwnedPeerState {
        has_result,
        mid_turn,
        round: u32::from(has_result),
        synthesized_round: 0,
    };
    let done_a = peer(true, false);
    let done_b = peer(true, false);

    // FIRES: >=1 peer, idle, all settled + done, marker absent.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[done_a, done_b], false, true),
        Fire,
    );

    // HOLDS while an owned peer is still running / has queued input (mid_turn).
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[done_a, peer(true, true)], false, true),
        Hold,
    );

    // HOLDS while the master is busy (even though the fleet is done).
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[done_a, done_b], false, false),
        Hold
    );

    // HOLDS when an owned peer has produced no result yet.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[done_a, peer(false, false)], false, true),
        Hold,
    );

    // EXACTLY ONCE PER ROUND: every peer's delivered round is already recorded
    // as summarized → HOLD, however many peers, and regardless of the stamp
    // flag. This is the guarantee the old existence marker provided; #2024 only
    // changed WHAT is compared, not that a summarized round stays summarized.
    let summarized = |round: u32| OwnedPeerState {
        has_result: true,
        mid_turn: false,
        round,
        synthesized_round: round,
    };
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[summarized(1), summarized(2), summarized(1)], true, true),
        Hold,
    );

    // Zero owned peers + no marker → nothing to do.
    assert_eq!(evaluate_peer_fleet_synthesis(&[], false, true), Hold);

    // RESET: zero owned peers + marker exists → ClearStamp (remove it) so a
    // genuinely fresh fleet can fire once later. Independent of idle.
    assert_eq!(evaluate_peer_fleet_synthesis(&[], true, true), ClearStamp);
    assert_eq!(evaluate_peer_fleet_synthesis(&[], true, false), ClearStamp);

    // After the reset (marker absent again) a fresh, complete fleet fires once.
    assert_eq!(evaluate_peer_fleet_synthesis(&[done_a], false, true), Fire);
}

/// Peer-fleet auto-synthesis — the interrupt terminal path now evaluates the
/// fleet too. An INTERRUPTED peer writes no fresh result.md, so: (a) HOLD when
/// it has no result yet (fleet not done), and (b) FIRE once when it already has
/// a prior result on the blackboard (persistent peer) and no marker exists yet.
#[test]
fn evaluate_holds_for_resultless_interrupt_and_fires_with_prior_result() {
    use FleetSynthesisDecision::{Fire, Hold};
    let peer = |has_result: bool| OwnedPeerState {
        has_result,
        mid_turn: false,
        round: u32::from(has_result),
        synthesized_round: 0,
    };
    let sibling_done = peer(true);

    // (a) Interrupted peer has NO result → fleet is not done → HOLD.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[sibling_done, peer(false)], false, true),
        Hold,
        "an interrupted peer with no result.md must not complete the fleet",
    );

    // (b) Interrupted peer already has a PRIOR result (persistent peer) + no
    // marker → the fleet is done → FIRE once.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[sibling_done, peer(true)], false, true),
        Fire,
        "an interrupted peer with a prior result still lets the fleet synthesize",
    );
}

/// #2024 — a SECOND round of peer work RE-ARMS the gate.
///
/// The pre-#2024 stamp was an existence marker: once written it held forever
/// while any owned peer lived, so a master that put its fleet through another
/// round never got a second write-up unless every peer was closed first. That
/// is the stall behind #2024. The stamp now records WHICH round of each peer
/// was summarized, and a peer that delivers a round past its mark re-arms.
#[test]
fn a_new_peer_round_re_arms_fleet_synthesis() {
    use FleetSynthesisDecision::{Fire, Hold};
    let peer = |round: u32, synthesized_round: u32| OwnedPeerState {
        has_result: true,
        mid_turn: false,
        round,
        synthesized_round,
    };

    // Round 1 delivered, nothing summarized yet → FIRE (unchanged).
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[peer(1, 0)], true, true),
        Fire
    );

    // Round 1 delivered AND summarized → HOLD. This is the exactly-once
    // guarantee the old existence stamp gave, and it is preserved.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[peer(1, 1)], true, true),
        Hold
    );

    // THE BUG: the peer did another round. The old gate held here forever;
    // now the unsummarized round 2 re-arms.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[peer(2, 1)], true, true),
        Fire
    );

    // ONE peer with fresh work is enough — the others being caught up does
    // not suppress it.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[peer(3, 3), peer(2, 1), peer(1, 1)], true, true),
        Fire,
    );

    // Whole fleet caught up → HOLD, however many peers.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[peer(3, 3), peer(2, 2), peer(1, 1)], true, true),
        Hold,
    );

    // A newly-added peer has no mark at all (synthesized_round 0) → FIRE.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[peer(2, 2), peer(1, 0)], true, true),
        Fire,
    );

    // Fresh work still does NOT override the settled/done/idle preconditions:
    // a busy master, a mid-turn peer, or a resultless peer all still HOLD.
    assert_eq!(
        evaluate_peer_fleet_synthesis(&[peer(2, 1)], true, false),
        Hold,
        "a busy master holds even with an unsummarized round",
    );
    assert_eq!(
        evaluate_peer_fleet_synthesis(
            &[
                peer(2, 1),
                OwnedPeerState {
                    has_result: true,
                    mid_turn: true,
                    round: 1,
                    synthesized_round: 1,
                },
            ],
            true,
            true,
        ),
        Hold,
        "a mid-turn sibling holds even with an unsummarized round elsewhere",
    );
    assert_eq!(
        evaluate_peer_fleet_synthesis(
            &[
                peer(2, 1),
                OwnedPeerState {
                    has_result: false,
                    mid_turn: false,
                    round: 0,
                    synthesized_round: 0,
                },
            ],
            true,
            true,
        ),
        Hold,
        "a resultless sibling holds even with an unsummarized round elsewhere",
    );
}

/// #2024 back-compat — a stamp written before this change is a bare unix
/// timestamp with no per-peer rounds. It proves the fleet WAS summarized but
/// not at which rounds, so every currently-owned peer reads as already covered
/// at its CURRENT round. An upgrade therefore never re-fires a fleet that was
/// already written up, while a genuinely new round still re-arms.
#[test]
fn a_legacy_peer_fleet_stamp_reads_as_every_current_round_summarized() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-1";

    // Exactly what the old code wrote: seconds-since-epoch, nothing else.
    std::fs::write(
        peer_fleet_synthesized_stamp_path(peers_root, master),
        "1755200000",
    )
    .unwrap();

    let marks = read_peer_fleet_synthesis_marks(peers_root, master);
    assert_eq!(marks, FleetSynthesisMarks::Legacy);

    // A legacy mark covers whatever round the peer is on right now...
    assert_eq!(synthesized_round_for(&marks, "any-slug", 4), 4);
    assert_eq!(synthesized_round_for(&marks, "other-slug", 1), 1);

    // ...so the fleet holds on upgrade rather than re-firing.
    assert_eq!(
        evaluate_peer_fleet_synthesis(
            &[OwnedPeerState {
                has_result: true,
                mid_turn: false,
                round: 4,
                synthesized_round: synthesized_round_for(&marks, "any-slug", 4),
            }],
            true,
            true,
        ),
        FleetSynthesisDecision::Hold,
        "upgrading must not re-synthesize an already-summarized fleet",
    );
}

/// #2024 — the stamp round-trips per-peer marks, and an absent stamp reads as
/// `None` (nothing summarized) rather than as a legacy marker.
#[test]
fn peer_fleet_synthesis_marks_round_trip_through_the_stamp_file() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-1";

    // No stamp at all → None, and every peer reads as unsummarized.
    let absent = read_peer_fleet_synthesis_marks(peers_root, master);
    assert_eq!(absent, FleetSynthesisMarks::None);
    assert_eq!(synthesized_round_for(&absent, "whatever", 3), 0);

    write_peer_fleet_synthesis_marks(
        peers_root,
        master,
        &[("alpha".to_owned(), 2), ("beta".to_owned(), 1)],
    )
    .expect("stamp write");

    let marks = read_peer_fleet_synthesis_marks(peers_root, master);
    assert_eq!(synthesized_round_for(&marks, "alpha", 2), 2);
    assert_eq!(synthesized_round_for(&marks, "beta", 1), 1);
    // A slug absent from the record is unsummarized — NOT covered-at-current
    // the way a legacy stamp would be.
    assert_eq!(synthesized_round_for(&marks, "gamma", 5), 0);

    // Rewriting replaces the record wholesale — a peer dropped from the fleet
    // does not linger in the stamp.
    write_peer_fleet_synthesis_marks(peers_root, master, &[("alpha".to_owned(), 3)])
        .expect("stamp rewrite");
    let rewritten = read_peer_fleet_synthesis_marks(peers_root, master);
    assert_eq!(synthesized_round_for(&rewritten, "alpha", 3), 3);
    assert_eq!(synthesized_round_for(&rewritten, "beta", 1), 0);
}

/// #2024 — a slug containing whitespace (the field separator) round-trips. The
/// stamp is keyed by slug, and slugs come from peer directory names, so the
/// encoding must not be defeated by one.
#[test]
fn peer_fleet_synthesis_marks_survive_a_slug_with_a_space() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-1";

    write_peer_fleet_synthesis_marks(
        peers_root,
        master,
        &[("two words".to_owned(), 2), ("plain".to_owned(), 1)],
    )
    .expect("stamp write");

    let marks = read_peer_fleet_synthesis_marks(peers_root, master);
    assert_eq!(synthesized_round_for(&marks, "two words", 2), 2);
    assert_eq!(
        synthesized_round_for(&marks, "plain", 1),
        1,
        "a space in one slug must not corrupt the rest of the record"
    );
}

/// #2024 — the round a peer is on is its count of versioned `result-<n>.md`
/// files, with one back-compat rule: a peer whose result predates versioning
/// (bare `result.md`, no `result-1.md`) still counts as round 1. Without that
/// floor such a peer would read as round 0, never exceed its mark, and never
/// synthesize at all.
#[test]
fn peer_result_round_counts_versions_and_floors_a_legacy_result_at_one() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-1";

    let stage = |slug: &str| {
        let dir = peers_root.join(slug);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("brief.md"), "brief").unwrap();
        std::fs::write(dir.join("originator"), master).unwrap();
        dir
    };

    // No result at all → round 0.
    stage("pending");
    // Legacy: bare result.md, no versioned files → floored to round 1.
    let legacy = stage("legacy");
    std::fs::write(legacy.join("result.md"), "res").unwrap();
    // Versioned: three rounds delivered.
    let versioned = stage("versioned");
    std::fs::write(versioned.join("result.md"), "res").unwrap();
    for n in 1..=3 {
        std::fs::write(versioned.join(format!("result-{n}.md")), "res").unwrap();
    }

    let owned = collect_owned_peer_results(peers_root, master).expect("peers dir readable");
    let round_of = |slug: &str| {
        owned
            .iter()
            .find(|peer| peer.slug == slug)
            .unwrap_or_else(|| panic!("{slug} owned"))
            .round
    };
    assert_eq!(round_of("pending"), 0, "no result → round 0");
    assert_eq!(round_of("legacy"), 1, "bare result.md floors to round 1");
    assert_eq!(round_of("versioned"), 3, "three result-<n>.md → round 3");
}

/// Peer-fleet auto-synthesis — `collect_owned_peer_results` returns exactly the
/// REAL staged peers whose `originator` matches the master, each paired with
/// whether it has a `result.md`; a peer with no result is present-but-`false`
/// (still in the fleet, blocks synthesis), an ERRORED peer's result still counts
/// as present, a CLOSED peer is excluded, and a peer owned by a DIFFERENT master
/// is excluded.
#[test]
fn collect_owned_peer_results_filters_by_originator_and_excludes_closed() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-1";
    let other = "tenant-a:api:master-2";

    let stage = |slug: &str, originator: &str| {
        let dir = peers_root.join(slug);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("brief.md"), "brief").unwrap();
        std::fs::write(dir.join("originator"), originator).unwrap();
        dir
    };

    // Owned + has a result.
    let done = stage("done-peer", master);
    std::fs::write(done.join("result.md"), "res").unwrap();
    // Owned, ERRORED terminal — result.md present, so it counts as done.
    let errored = stage("errored-peer", master);
    std::fs::write(errored.join("result.md"), "err body").unwrap();
    // Owned but NO result yet (blocks synthesis; still part of the fleet).
    stage("pending-peer", master);
    // Owned but CLOSED — excluded (retired peer).
    let closed = stage("closed-peer", master);
    std::fs::write(closed.join("result.md"), "res").unwrap();
    std::fs::write(closed.join("closed"), "").unwrap();
    // Owned by a DIFFERENT master — excluded.
    let foreign = stage("foreign-peer", other);
    std::fs::write(foreign.join("result.md"), "res").unwrap();

    let mut owned = collect_owned_peer_results(peers_root, master).expect("peers dir readable");
    owned.sort();
    let slugs: Vec<&str> = owned.iter().map(|peer| peer.slug.as_str()).collect();
    assert_eq!(
        slugs,
        vec!["done-peer", "errored-peer", "pending-peer"],
        "only this master's non-closed peers are owned"
    );
    let has_result = |slug: &str| {
        owned
            .iter()
            .find(|peer| peer.slug == slug)
            .unwrap_or_else(|| panic!("{slug} owned"))
            .has_result
    };
    assert!(
        has_result("done-peer"),
        "a written result → has_result true"
    );
    assert!(
        has_result("errored-peer"),
        "an errored peer's result.md still counts as present"
    );
    assert!(
        !has_result("pending-peer"),
        "a peer with no result.md → has_result false"
    );
}

/// Peer-fleet auto-synthesis — the per-master `.synthesized` stamp FILE's
/// lifecycle: create/exists/remove round-trips, distinct masters are independent
/// (`safe_filename`), removing an absent stamp is a no-op, and the colocated
/// stamp file is never mistaken for a staged peer.
///
/// This covers the file only. What the stamp SAYS — per-peer summarized rounds
/// since #2024 — is covered by
/// `peer_fleet_synthesis_marks_round_trip_through_the_stamp_file`.
#[test]
fn peer_fleet_synthesized_stamp_file_lifecycle() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master_a = "tenant-a:api:master-1";
    let master_b = "tenant-a:api:master-2";

    assert!(!peer_fleet_synthesized_stamp_exists(peers_root, master_a));

    // Create. Content is irrelevant here — `..._exists` gates only the
    // ClearStamp tidy-up, which does not read the record.
    crate::memory_consolidate::apply::atomic_write(
        &peer_fleet_synthesized_stamp_path(peers_root, master_a),
        "1721900000",
    )
    .unwrap();
    assert!(peer_fleet_synthesized_stamp_exists(peers_root, master_a));
    // A different master is independent.
    assert!(!peer_fleet_synthesized_stamp_exists(peers_root, master_b));

    // Remove clears it; removing an absent marker is a no-op (no panic).
    remove_peer_fleet_synthesized_stamp(peers_root, master_a);
    assert!(!peer_fleet_synthesized_stamp_exists(peers_root, master_a));
    remove_peer_fleet_synthesized_stamp(peers_root, master_b);

    // The colocated marker file is NOT mistaken for a staged peer.
    crate::memory_consolidate::apply::atomic_write(
        &peer_fleet_synthesized_stamp_path(peers_root, master_a),
        "x",
    )
    .unwrap();
    assert!(
        collect_owned_peer_results(peers_root, master_a)
            .expect("peers dir readable")
            .is_empty()
    );
}

/// Peer-fleet auto-synthesis RESET — `reset_peer_fleet_synthesis_if_cleared`
/// removes the marker ONLY when the master's owned fleet is fully cleared. While
/// any owned (non-closed) peer remains the marker persists; once the last peer
/// is closed the marker is dropped so a fresh fleet fires once later.
#[test]
fn reset_removes_marker_only_when_fleet_fully_cleared() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-1";

    // One owned, completed peer + the synthesized marker.
    let dir = peers_root.join("worker");
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("brief.md"), "brief").unwrap();
    std::fs::write(dir.join("originator"), master).unwrap();
    std::fs::write(dir.join("result.md"), "res").unwrap();
    crate::memory_consolidate::apply::atomic_write(
        &peer_fleet_synthesized_stamp_path(peers_root, master),
        "1721900000",
    )
    .unwrap();

    // Reset while an owned peer remains → marker PERSISTS.
    reset_peer_fleet_synthesis_if_cleared(peers_root, master);
    assert!(
        peer_fleet_synthesized_stamp_exists(peers_root, master),
        "marker persists while any owned peer remains"
    );

    // Close the peer (exclude it from the owned scan) → fleet cleared.
    std::fs::write(dir.join("closed"), "").unwrap();
    reset_peer_fleet_synthesis_if_cleared(peers_root, master);
    assert!(
        !peer_fleet_synthesized_stamp_exists(peers_root, master),
        "marker removed once the fleet is fully cleared (a fresh fleet re-fires)"
    );
}

/// #2003 — a fleet whose LAST peer lands while the master is BUSY must still
/// synthesize once the master goes idle.
///
/// This is the case that produced "the master just stopped". The gate used to
/// be evaluated only on a peer's terminal edge, and `Hold` was discarded with
/// nothing rescheduled — so once every peer was terminal there was no event
/// left to re-trigger it, and the `Fire` was lost forever. Clearing a wedged
/// in-flight marker (#2004/#2014) does not help: it does not re-run the gate.
///
/// Drives the shared evaluation the way the MASTER edge does, and asserts the
/// observable effect — the `.synthesized-<master>` stamp — rather than the
/// decision value, so it fails if the master edge stops being reachable.
#[tokio::test]
async fn fleet_that_landed_while_master_was_busy_synthesizes_on_the_master_idle_edge() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-rearm";
    let master_key = SessionKey(master.to_owned());

    let stage = |slug: &str| {
        let dir = peers_root.join(slug);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("brief.md"), "brief").unwrap();
        std::fs::write(dir.join("originator"), master).unwrap();
        // Landed: has a result and no live turn.
        std::fs::write(dir.join("result.md"), "findings").unwrap();
    };
    stage("peer-one");
    stage("peer-two");

    // The master is BUSY: a live (non-terminal) turn is registered for it.
    let abort = tokio::spawn(async {}).abort_handle();
    let busy_turn = test_active_turn(TurnId::new(), abort);
    active_turns_registry()
        .lock()
        .await
        .insert(master_key.clone(), busy_turn);

    // 1. The PEER edge, with the master busy. This is the moment the last peer
    //    lands. `master_idle` is false, so the gate Holds — and the old code
    //    dropped that decision with nothing rescheduled.
    let landing_peer = SessionKey(format!("{MAIN_PROFILE_ID}:api:peer-two"));
    evaluate_and_enqueue_fleet_synthesis(MAIN_PROFILE_ID, peers_root, master, &landing_peer).await;
    assert!(
        !peer_fleet_synthesized_stamp_exists(peers_root, master),
        "precondition: a busy master must NOT synthesize on the peer edge"
    );

    // 2. The MASTER-idle edge (#2003): the master's own turn is the one
    //    terminating, so it is excluded from the active-turn set — which is
    //    precisely what flips `master_idle` true and recovers the lost Fire.
    //    Every peer is already terminal here, so without this edge NOTHING
    //    would ever re-evaluate the gate and the master would wait forever.
    evaluate_and_enqueue_fleet_synthesis(MAIN_PROFILE_ID, peers_root, master, &master_key).await;
    assert!(
        peer_fleet_synthesized_stamp_exists(peers_root, master),
        "a complete fleet must synthesize once the master goes idle; without \
         the re-arm the Fire is lost when the last peer lands on a busy master"
    );

    active_turns_registry().lock().await.remove(&master_key);
}

/// #2024 END-TO-END — a peer's SECOND round produces a SECOND synthesis, driven
/// through the real `evaluate_and_enqueue_fleet_synthesis` rather than the pure
/// decision.
///
/// This is the case the pure-function tests cannot reach and that the fix
/// initially got wrong. The synthesis continuation's dedupe key is stable per
/// master, so round 2's enqueue lands as a DUPLICATE while round 1's is still
/// pending. With the marks advanced before the enqueue, round 2 would be
/// recorded as summarized by a turn that never ran, and nothing would retry —
/// the gate fix alone would have lost the second synthesis silently while every
/// unit test passed.
///
/// Asserts the marks on disk, because they are what the gate reads next time.
#[tokio::test]
async fn a_second_peer_round_is_not_recorded_as_summarized_unless_a_turn_actually_queued() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    // Unique master: the dedupe key and its recent-claim guard are
    // process-global, so a shared name would collide with sibling tests.
    let master = "tenant-a:api:master-2024-e2e";
    let master_key = SessionKey(master.to_owned());

    let dir = peers_root.join("worker");
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("brief.md"), "brief").unwrap();
    std::fs::write(dir.join("originator"), master).unwrap();

    // ROUND 1: the peer delivers. Master-idle edge → fires, records round 1.
    std::fs::write(dir.join("result.md"), "round one").unwrap();
    std::fs::write(dir.join("result-1.md"), "round one").unwrap();
    evaluate_and_enqueue_fleet_synthesis(MAIN_PROFILE_ID, peers_root, master, &master_key).await;
    assert_eq!(
        synthesized_round_for(
            &read_peer_fleet_synthesis_marks(peers_root, master),
            "worker",
            1
        ),
        1,
        "round 1 queued a synthesis, so it must be recorded as summarized",
    );

    // Re-evaluating with NOTHING new must not disturb the record.
    evaluate_and_enqueue_fleet_synthesis(MAIN_PROFILE_ID, peers_root, master, &master_key).await;
    assert_eq!(
        synthesized_round_for(
            &read_peer_fleet_synthesis_marks(peers_root, master),
            "worker",
            1
        ),
        1,
        "an evaluation with no new round is a no-op",
    );

    // ROUND 2: the master sent a follow-up and the peer delivered again. The
    // gate re-arms — but a synthesis for this master is already in flight, so
    // the enqueue DEDUPES. The mark must therefore stay at 1, leaving the gate
    // armed for the next edge instead of recording a synthesis that never ran.
    //
    // Establish that precondition EXPLICITLY rather than relying on round 1's
    // continuation still sitting in the process-global queue: sibling tests
    // share that queue, and depending on its state made this test flaky in a
    // full parallel run (the #2029 disease — do not add another instance of
    // it). A redundant enqueue on the same per-master key is a no-op if one is
    // already pending, so this is safe either way.
    default_agent_orchestrator().enqueue_peer_fleet_synthesis_continuation(
        &master_key,
        MAIN_PROFILE_ID,
        &["worker".to_owned()],
        1,
    );
    std::fs::write(dir.join("result.md"), "round two").unwrap();
    std::fs::write(dir.join("result-2.md"), "round two").unwrap();
    evaluate_and_enqueue_fleet_synthesis(MAIN_PROFILE_ID, peers_root, master, &master_key).await;
    assert_eq!(
        synthesized_round_for(
            &read_peer_fleet_synthesis_marks(peers_root, master),
            "worker",
            2
        ),
        1,
        "a deduped enqueue must NOT record round 2 as summarized — otherwise \
         the second synthesis is lost with nothing left to retry it",
    );

    // And the gate is still armed: round 2 > recorded 1.
    let owned = collect_owned_peer_results(peers_root, master).expect("peers dir readable");
    let marks = read_peer_fleet_synthesis_marks(peers_root, master);
    let states: Vec<OwnedPeerState> = owned
        .iter()
        .map(|peer| OwnedPeerState {
            has_result: peer.has_result,
            mid_turn: false,
            round: peer.round,
            synthesized_round: synthesized_round_for(&marks, &peer.slug, peer.round),
        })
        .collect();
    assert_eq!(
        evaluate_peer_fleet_synthesis(&states, true, true),
        FleetSynthesisDecision::Fire,
        "round 2 stays armed so the next terminal retries the synthesis",
    );
}

/// #2033 — a synthesis that was OWED when the process died must be evaluated at
/// BOOT, not left waiting for the next unrelated turn.
///
/// The gate is EDGE-triggered: `evaluate_and_enqueue_fleet_synthesis` is reached
/// from exactly two edges, a PEER turn terminal and a MASTER turn terminal.
/// Normally that is enough — a deduped enqueue deliberately leaves the marks
/// behind (#2024) and the in-flight synthesis continuation's OWN terminal is the
/// retry edge. What has no edge at all is a process restart: if the owed round's
/// retry edge was still in the future when the process died, nothing on the new
/// process ever recomputes the gate.
///
/// Observed live (mini5 soak): a peer's round-2 terminal landed while a round-1
/// synthesis was in flight, so the enqueue deduped and the marks stayed at
/// `1 auditor`; the serve was then killed before that continuation reached its
/// terminal. On restart the master session was opened and sat for 220s with the
/// marks still at round 1 — one trivial master turn advanced them in 3s. The
/// peer's last round is only ever written up if the user happens to type again.
///
/// Reconstructs exactly that on-disk state — peer delivered round 2, marks
/// recorded at round 1, nothing in flight — and asserts the BOOT sweep fires it
/// with NO turn edge whatsoever. The already-current fleet in the same
/// `peers/` root must NOT be evaluated: the sweep is bounded to owed fleets.
#[tokio::test]
async fn boot_sweep_synthesizes_a_peer_fleet_round_left_owed_when_the_process_died() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    // Unique masters/slugs: the continuation dedupe key, its recent-claim
    // guard, and the peer wire registry are all process-global, so shared names
    // would collide with sibling tests in a parallel run (#2029).
    let owed_master = "tenant-a:api:master-2033-owed";
    let current_master = "tenant-a:api:master-2033-current";

    let stage = |slug: &str, master: &str, rounds: u32| {
        let dir = peers_root.join(slug);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("brief.md"), "brief").unwrap();
        std::fs::write(dir.join("originator"), master).unwrap();
        std::fs::write(dir.join("result.md"), "findings").unwrap();
        for round in 1..=rounds {
            std::fs::write(dir.join(format!("result-{round}.md")), "findings").unwrap();
        }
    };
    // OWED: delivered round 2, only round 1 recorded as summarized.
    stage("auditor-2033", owed_master, 2);
    write_peer_fleet_synthesis_marks(peers_root, owed_master, &[("auditor-2033".to_owned(), 1)])
        .unwrap();
    // CURRENT: delivered round 1, round 1 already summarized. Nothing owed.
    stage("scribe-2033", current_master, 1);
    write_peer_fleet_synthesis_marks(peers_root, current_master, &[("scribe-2033".to_owned(), 1)])
        .unwrap();

    // Precondition: the owed fleet's record is genuinely behind its delivery.
    assert_eq!(
        synthesized_round_for(
            &read_peer_fleet_synthesis_marks(peers_root, owed_master),
            "auditor-2033",
            2
        ),
        1,
        "precondition: the round-2 delivery is recorded as summarized only through round 1",
    );

    // The BOOT sweep — no peer terminal, no master terminal, no client.
    let evaluated = enqueue_boot_owed_peer_fleet_synthesis(MAIN_PROFILE_ID, peers_root).await;

    assert_eq!(
        synthesized_round_for(
            &read_peer_fleet_synthesis_marks(peers_root, owed_master),
            "auditor-2033",
            2
        ),
        2,
        "boot must enqueue the owed synthesis and advance the marks; without a \
         boot-time evaluation the round waits for an unrelated turn, forever on \
         a quiet fleet",
    );
    assert_eq!(
        evaluated, 1,
        "exactly the OWED fleet is evaluated; a fleet with nothing new must not \
         be re-evaluated (the sweep is bounded to owed fleets, not a full scan)",
    );
    assert_eq!(
        synthesized_round_for(
            &read_peer_fleet_synthesis_marks(peers_root, current_master),
            "scribe-2033",
            1
        ),
        1,
        "an already-summarized fleet is untouched by the boot sweep",
    );
}

/// #2033 — the boot sweep only decides WHICH fleets to look at; whether one
/// fires stays with the shared gate.
///
/// "Owed" (a delivered round past the recorded mark) is a strictly weaker
/// condition than "ready": it says nothing about the other peers in the fleet.
/// A sweep that wrote the marks itself — or that treated owed as fire — would
/// summarize a fleet mid-flight and, because the marks advance, never write up
/// the sibling's work at all. Here one peer is owed at round 2 while a sibling
/// has not delivered anything, so the fleet must be selected and then HELD.
#[tokio::test]
async fn boot_sweep_selects_an_owed_peer_fleet_but_leaves_the_fire_decision_to_the_gate() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path();
    let master = "tenant-a:api:master-2033-unfinished";

    // Owed: delivered round 2, recorded at round 1.
    let delivered = peers_root.join("auditor-2033-unfinished");
    std::fs::create_dir_all(&delivered).unwrap();
    std::fs::write(delivered.join("brief.md"), "brief").unwrap();
    std::fs::write(delivered.join("originator"), master).unwrap();
    std::fs::write(delivered.join("result.md"), "findings").unwrap();
    std::fs::write(delivered.join("result-1.md"), "findings").unwrap();
    std::fs::write(delivered.join("result-2.md"), "findings").unwrap();
    // Sibling in the SAME fleet with no result at all — the fleet is not done.
    let pending = peers_root.join("scribe-2033-unfinished");
    std::fs::create_dir_all(&pending).unwrap();
    std::fs::write(pending.join("brief.md"), "brief").unwrap();
    std::fs::write(pending.join("originator"), master).unwrap();
    write_peer_fleet_synthesis_marks(
        peers_root,
        master,
        &[("auditor-2033-unfinished".to_owned(), 1)],
    )
    .unwrap();

    let evaluated = enqueue_boot_owed_peer_fleet_synthesis(MAIN_PROFILE_ID, peers_root).await;

    assert_eq!(
        evaluated, 1,
        "the fleet IS owed, so the sweep must hand it to the gate",
    );
    assert_eq!(
        synthesized_round_for(
            &read_peer_fleet_synthesis_marks(peers_root, master),
            "auditor-2033-unfinished",
            2
        ),
        1,
        "the gate holds an unfinished fleet, so the boot sweep must not advance \
         the marks — advancing them here would lose the sibling's round entirely",
    );
}

/// Bug 2 (reset edge) — `collect_owned_peer_results` distinguishes a
/// genuinely-EMPTY readable directory (`Some(vec![])`) from a `peers/` scan
/// FAILURE (`None`), so a transient read error is never mistaken for a cleared
/// fleet.
#[test]
fn collect_owned_peer_results_distinguishes_empty_from_scan_failure() {
    let tmp = tempfile::tempdir().unwrap();
    let master = "tenant-a:api:master-scan";

    // Genuinely-empty (readable) dir → Some(empty).
    let empty = tmp.path().join("empty-peers");
    std::fs::create_dir_all(&empty).unwrap();
    assert_eq!(
        collect_owned_peer_results(&empty, master),
        Some(Vec::new()),
        "an empty readable dir is Some(empty), not a failure"
    );

    // Non-existent dir → read_dir fails → None (distinct from Some(empty)).
    let missing = tmp.path().join("missing-peers");
    assert_eq!(
        collect_owned_peer_results(&missing, master),
        None,
        "a read_dir failure must be None (fail-closed), not Some(empty)"
    );
}

/// Bug 2 (reset edge) — a `peers/` scan FAILURE must fail closed: the reset does
/// NOT remove an existing marker (which would let an already-synthesized fleet
/// re-fire). Exercised on Unix by denying READ (keeping EXECUTE) on `peers/` so
/// `read_dir` fails while the marker stat still succeeds. Skipped when perms are
/// not enforced (e.g. running as root).
#[cfg(unix)]
#[test]
fn scan_failure_does_not_reset_marker() {
    use std::os::unix::fs::PermissionsExt;
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path().join("peers");
    std::fs::create_dir_all(&peers_root).unwrap();
    let master = "tenant-a:api:master-scan";

    // Marker present (written while the dir is readable).
    crate::memory_consolidate::apply::atomic_write(
        &peer_fleet_synthesized_stamp_path(&peers_root, master),
        "1721900000",
    )
    .unwrap();

    // Deny READ but keep EXECUTE: read_dir fails, stat(marker) still works.
    std::fs::set_permissions(&peers_root, std::fs::Permissions::from_mode(0o111)).unwrap();
    if std::fs::read_dir(&peers_root).is_ok() {
        // Permissions not enforced (root); can't exercise the failure path.
        std::fs::set_permissions(&peers_root, std::fs::Permissions::from_mode(0o755)).unwrap();
        return;
    }

    // Exercise the fail-closed path while read is denied.
    let collect_result = collect_owned_peer_results(&peers_root, master);
    reset_peer_fleet_synthesis_if_cleared(&peers_root, master);

    // Restore read for the marker check + tempdir cleanup, THEN assert (so a
    // panic can't leave the dir unreadable).
    std::fs::set_permissions(&peers_root, std::fs::Permissions::from_mode(0o755)).unwrap();
    assert_eq!(
        collect_result, None,
        "a read_dir failure yields None (fail-closed)"
    );
    assert!(
        peer_fleet_synthesized_stamp_exists(&peers_root, master),
        "a scan failure must NOT reset the marker (fail-closed)"
    );
}

/// codex #6 — `stage_peer` records the ORIGINATOR (when supplied) so the
/// fleet-ownership scan reliably attributes the peer to its master, and does so
/// alongside `brief.md` (both present after a successful stage). A `None`
/// originator (profile-scoped prepare) leaves no owner file and is unowned.
#[test]
fn stage_peer_records_originator_for_ownership_scan() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path().join("peers");
    std::fs::create_dir_all(&peers_root).unwrap();
    let ws = tmp.path().join("ws");
    std::fs::create_dir_all(&ws).unwrap();
    let master = "tenant-a:api:master-1";

    // Owned peer: originator threaded in → recorded beside brief.md.
    let owned = stage_peer(
        &peers_root,
        &ws,
        "seed",
        Some("Curie"),
        Some(master),
        "Brief.",
        false,
        None,
        None,
    )
    .expect("owned staging");
    let owned_dir = peers_root.join(&owned.slug);
    assert!(owned_dir.join("brief.md").is_file(), "brief.md written");
    assert_eq!(
        std::fs::read_to_string(owned_dir.join("originator")).unwrap(),
        master,
        "originator recorded for the owning master"
    );

    // Unowned peer: no originator supplied → no owner file.
    let unowned = stage_peer(
        &peers_root,
        &ws,
        "seed",
        Some("Bohr"),
        None,
        "Brief.",
        false,
        None,
        None,
    )
    .expect("unowned staging");
    assert!(
        !peers_root.join(&unowned.slug).join("originator").exists(),
        "a None originator leaves no owner file"
    );

    // The ownership scan attributes ONLY the owned peer to the master.
    let owned_slugs: Vec<String> = collect_owned_peer_results(&peers_root, master)
        .expect("peers dir readable")
        .into_iter()
        .map(|peer| peer.slug)
        .collect();
    assert_eq!(
        owned_slugs,
        vec![owned.slug],
        "only the owned peer is in the fleet"
    );
}

/// #436 P1 #2 — a peer continuation is only drained by the connection that has
/// the peer session open, so its live (ephemeral) turn output never renders on
/// another same-profile client. Non-peer targets are unaffected.
#[test]
fn peer_continuation_only_drained_by_owning_connection() {
    let peer = SessionKey::with_profile_topic("tenant-a", "api", "tab-1", "peer-slugz");
    let goal_session = SessionKey::with_profile("tenant-a", "api", "master");
    let master_open: std::collections::HashSet<SessionKey> =
        [goal_session.clone()].into_iter().collect();
    let peer_open: std::collections::HashSet<SessionKey> = [peer.clone()].into_iter().collect();

    // Master hasn't opened the peer → must NOT run the peer's turn.
    assert!(!peer_target_deliverable_on_connection(&peer, &master_open));
    // The peer's own connection → runs it (live output reaches the peer).
    assert!(peer_target_deliverable_on_connection(&peer, &peer_open));
    // Non-peer targets (goal/loop) — any connection may drain, as before.
    assert!(peer_target_deliverable_on_connection(
        &goal_session,
        &master_open
    ));
    assert!(peer_target_deliverable_on_connection(
        &goal_session,
        &std::collections::HashSet::new()
    ));
}

/// #436 P1 #3 — a durable-persist failure must surface as an ERROR, never a
/// false success ack; a queued/duplicate injection is a success.
#[test]
fn peer_send_input_persist_failure_maps_to_error_not_success() {
    use crate::autonomy::agent_orchestrator::PeerSendInputEnqueueOutcome;
    let err = PeerSendInputEnqueueOutcome::PersistFailed
        .into_callback_result("slugz")
        .expect_err("persist failure must be an error, not a success ack");
    assert!(
        err.contains("slugz") && err.contains("not delivered"),
        "reason: {err}"
    );
    assert!(
        PeerSendInputEnqueueOutcome::Queued
            .into_callback_result("slugz")
            .is_ok()
    );
    assert!(
        PeerSendInputEnqueueOutcome::Duplicate
            .into_callback_result("slugz")
            .is_ok()
    );
}

/// #436 P1 #1 — on reconnect the peer opens under a NEW client-chosen wire key;
/// a queued injection must be RE-HOMED to the new session, not stranded on the
/// closed one.
#[tokio::test]
async fn peer_send_input_rehomes_to_reopened_peer_wire_on_reconnect() {
    use crate::autonomy::agent_orchestrator::PeerSendInputEnqueueOutcome;
    let orchestrator = default_agent_orchestrator();
    let profile_id = "test-peer-reconnect-rehome";
    let slug = "reconnect-peer";
    let s1 = SessionKey::with_profile_topic(profile_id, "api", "conn-1", &format!("peer-{slug}"));
    let s2 = SessionKey::with_profile_topic(profile_id, "api", "conn-2", &format!("peer-{slug}"));
    // An empty state has no registered profile runtime, so the close-marker
    // skip is a no-op here — retarget behaves exactly as before this fix.
    let state = Arc::new(AppState::empty_for_tests());

    // Peer opens as S1; an injection is queued against S1.
    register_peer_wire_session(&state, &s1);
    let outcome = orchestrator.enqueue_peer_send_input_continuation(
        &s1,
        profile_id,
        slug,
        "call-x",
        "resume work",
    );
    assert_eq!(outcome, PeerSendInputEnqueueOutcome::Queued);
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&s1, profile_id),
        1
    );

    // Peer reopens as a NEW wire key S2 → the stranded injection is re-homed.
    register_peer_wire_session(&state, &s2);
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&s1, profile_id),
        0,
        "the injection must not remain stranded on the closed S1",
    );
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&s2, profile_id),
        1,
        "the injection must be re-homed to the reopened S2",
    );
    assert_eq!(
        peer_wire_registry().resolve(&peer_wire_key(profile_id, slug)),
        Some(s2.clone()),
        "registry reflects latest-wins wire",
    );
    // The re-homed continuation still renders the original text verbatim.
    let drained = orchestrator.drain_ready_continuations_for_session(
        &s2,
        profile_id,
        crate::autonomy::master_continuation_scheduler::MasterContinuationRuntimeState::idle(),
        8,
    );
    assert_eq!(drained.len(), 1);
    assert_eq!(master_continuation_prompt(&drained[0]), "resume work");
}

/// #436 P1 #5 — a closing peer is evicted from the wire registry so it is no
/// longer a stale injection target; a stale close must not clobber a session
/// that already reopened.
#[test]
fn peer_wire_registry_evicts_on_close_conditionally() {
    let profile_id = "test-peer-evict-close";
    let slug = "evict-peer";
    let s1 = SessionKey::with_profile_topic(profile_id, "api", "c1", &format!("peer-{slug}"));
    let state = Arc::new(AppState::empty_for_tests());
    register_peer_wire_session(&state, &s1);
    assert_eq!(
        peer_wire_registry().resolve(&peer_wire_key(profile_id, slug)),
        Some(s1.clone())
    );

    // Close S1 → evicted.
    evict_peer_wire_session(&s1);
    assert_eq!(
        peer_wire_registry().resolve(&peer_wire_key(profile_id, slug)),
        None,
        "a closed peer must not remain a resolvable target",
    );

    // Race: peer reopened as S2 before S1's close lands — the stale close of S1
    // must NOT evict the fresh S2 mapping.
    let s2 = SessionKey::with_profile_topic(profile_id, "api", "c2", &format!("peer-{slug}"));
    register_peer_wire_session(&state, &s2);
    evict_peer_wire_session(&s1);
    assert_eq!(
        peer_wire_registry().resolve(&peer_wire_key(profile_id, slug)),
        Some(s2),
        "a stale close must not evict the reopened session",
    );
}

/// #436 P1 #2 — a peer_send_input injection is completed only if its turn
/// dispatched the agent; an undispatched one (e.g. failed `TurnStarted`) stays
/// durable for retry/replay. Non-peer continuations always complete.
#[test]
fn peer_injection_completes_only_when_dispatched() {
    assert!(
        continuation_may_complete(true, true),
        "a dispatched peer injection completes",
    );
    assert!(
        !continuation_may_complete(true, false),
        "an undispatched peer injection stays durable (not completed)",
    );
    // Non-peer continuations are unaffected — completed regardless.
    assert!(continuation_may_complete(false, true));
    assert!(continuation_may_complete(false, false));
}

/// #436 P1 #3 — the connection-independent global drain runs a peer injection
/// only under the slug's CURRENT registered wire: an obsolete (superseded) or
/// closed (evicted) wire is skipped and delivered on reopen. Non-peer targets
/// always pass.
#[test]
fn global_drain_skips_obsolete_or_closed_peer_wire() {
    let profile_id = "test-peer-freshness-gate";
    let slug = "freshness-peer";
    let s1 = SessionKey::with_profile_topic(profile_id, "api", "c1", &format!("peer-{slug}"));
    let s2 = SessionKey::with_profile_topic(profile_id, "api", "c2", &format!("peer-{slug}"));
    let state = Arc::new(AppState::empty_for_tests());

    register_peer_wire_session(&state, &s1);
    assert!(peer_target_is_current_wire(&s1), "current wire is runnable");

    // Reopen as S2 → S1 is now obsolete.
    register_peer_wire_session(&state, &s2);
    assert!(
        !peer_target_is_current_wire(&s1),
        "an obsolete wire must be skipped by the global drain",
    );
    assert!(peer_target_is_current_wire(&s2), "the new wire is runnable");

    // Close S2 → no current wire; skipped (delivered on reopen).
    evict_peer_wire_session(&s2);
    assert!(
        !peer_target_is_current_wire(&s2),
        "a closed peer wire must be skipped",
    );

    // Non-peer targets are never gated.
    assert!(peer_target_is_current_wire(&SessionKey::with_profile(
        profile_id, "api", "master"
    )));
}

/// #436 P1 #3 — retarget TOMBSTONES the old durable record, so a restart does
/// NOT resurrect + re-deliver the obsolete-wire injection. Simulated with two
/// isolated orchestrators sharing one supervisor store: after retarget, a
/// fresh orchestrator restoring the store re-enqueues exactly one injection,
/// under the NEW wire (not the old).
#[test]
fn retarget_tombstones_old_durable_record_no_restart_dup() {
    use crate::autonomy::agent_orchestrator::{
        InProcessAgentOrchestrator, PeerSendInputEnqueueOutcome,
    };
    let dir = tempfile::tempdir().unwrap();
    let profile_id = "tenant-a";
    let slug = "restart-dup-peer";
    let s1 = SessionKey::with_profile_topic(profile_id, "api", "c1", &format!("peer-{slug}"));
    let s2 = SessionKey::with_profile_topic(profile_id, "api", "c2", &format!("peer-{slug}"));

    // Pre-restart orchestrator, durably backed.
    let orch1 = InProcessAgentOrchestrator::default();
    orch1.configure_supervisor_store(dir.path()).unwrap();
    let outcome =
        orch1.enqueue_peer_send_input_continuation(&s1, profile_id, slug, "call-1", "resume");
    assert_eq!(outcome, PeerSendInputEnqueueOutcome::Queued);
    // Peer reopened as S2 → re-home (tombstones the old S1 durable record).
    assert_eq!(
        orch1.retarget_peer_send_input_continuations(profile_id, slug, &s2),
        1,
        "the stranded S1 injection is re-homed to S2",
    );

    // Simulate a restart: a fresh orchestrator restores from the SAME store.
    let orch2 = InProcessAgentOrchestrator::default();
    orch2.configure_supervisor_store(dir.path()).unwrap();
    assert_eq!(
        orch2.pending_continuation_count_for_session_for_test(&s1, profile_id),
        0,
        "the tombstoned old record must NOT be resurrected on restart",
    );
    assert_eq!(
        orch2.pending_continuation_count_for_session_for_test(&s2, profile_id),
        1,
        "exactly one injection is restored, under the current wire",
    );
}

/// #436 P1 #1 — retarget must persist the NEW durable record BEFORE tombstoning
/// the OLD one, so a crash between the two writes can never lose the injection
/// (worst case both survive, never "neither"). Asserted on the durable event
/// log: the new record's queue event precedes the old record's completed
/// (tombstone) event.
#[test]
fn retarget_persists_new_before_tombstoning_old_crash_safe() {
    use crate::autonomy::agent_orchestrator::{
        InProcessAgentOrchestrator, PeerSendInputEnqueueOutcome,
    };
    let dir = tempfile::tempdir().unwrap();
    let orch = InProcessAgentOrchestrator::default();
    orch.configure_supervisor_store(dir.path()).unwrap();
    let profile_id = "tenant-a";
    let slug = "crash-order-peer";
    let s1 = SessionKey::with_profile_topic(profile_id, "api", "c1", &format!("peer-{slug}"));
    let s2 = SessionKey::with_profile_topic(profile_id, "api", "c2", &format!("peer-{slug}"));
    assert_eq!(
        orch.enqueue_peer_send_input_continuation(&s1, profile_id, slug, "call-1", "work"),
        PeerSendInputEnqueueOutcome::Queued
    );
    assert_eq!(
        orch.retarget_peer_send_input_continuations(profile_id, slug, &s2),
        1
    );

    let events = std::fs::read_to_string(
        crate::autonomy::supervisor_store::SupervisorStore::new(dir.path()).events_path(),
    )
    .unwrap();
    let lines: Vec<&str> = events.lines().collect();
    // The NEW record's queue event is the only one mentioning the S2 wire.
    let new_queued_idx = lines
        .iter()
        .position(|l| l.contains("c2#peer-crash-order-peer"))
        .expect("new record queue event present");
    // The OLD record's tombstone is the (only) `continuation_completed` event.
    let old_completed_idx = lines
        .iter()
        .position(|l| l.contains("continuation_completed"))
        .expect("old record tombstone present");
    assert!(
        new_queued_idx < old_completed_idx,
        "the new record must be persisted BEFORE the old is tombstoned \
         (new_queued={new_queued_idx}, old_completed={old_completed_idx})",
    );
}

/// #436 P1 #2/#4 — an injection that was popped (claimed) but NOT delivered
/// (failed dispatch, or an obsolete wire) is RE-INSERTED so it is retryable
/// live on the next tick — the recently-claimed guard must not block the
/// redraw. Without this it would only ever re-deliver at a server restart.
#[test]
fn reinsert_makes_popped_injection_drainable_again() {
    use crate::autonomy::agent_orchestrator::{
        InProcessAgentOrchestrator, PeerSendInputEnqueueOutcome,
    };
    use crate::autonomy::master_continuation_scheduler::MasterContinuationRuntimeState;
    let orch = InProcessAgentOrchestrator::default();
    let profile_id = "test-peer-reinsert";
    let slug = "reinsert-peer";
    let s = SessionKey::with_profile_topic(profile_id, "api", "c1", &format!("peer-{slug}"));
    assert_eq!(
        orch.enqueue_peer_send_input_continuation(&s, profile_id, slug, "call-1", "retry me"),
        PeerSendInputEnqueueOutcome::Queued
    );

    // Drain (pop) — removes it from pending and records the recently-claimed
    // guard entry.
    let drained = orch.drain_ready_continuations_for_session(
        &s,
        profile_id,
        MasterContinuationRuntimeState::idle(),
        1,
    );
    assert_eq!(drained.len(), 1);
    assert_eq!(
        orch.pending_continuation_count_for_session_for_test(&s, profile_id),
        0
    );

    // Undelivered → re-insert. It must be pending AND drainable again (the
    // recently-claimed guard is cleared for a not-delivered restore).
    orch.reinsert_peer_continuation(drained.into_iter().next().unwrap());
    assert_eq!(
        orch.pending_continuation_count_for_session_for_test(&s, profile_id),
        1,
        "the undelivered injection is re-queued for live retry",
    );
    let redrained = orch.drain_ready_continuations_for_session(
        &s,
        profile_id,
        MasterContinuationRuntimeState::idle(),
        1,
    );
    assert_eq!(
        redrained.len(),
        1,
        "the re-inserted injection is retryable on the next tick",
    );
    assert_eq!(master_continuation_prompt(&redrained[0]), "retry me");
}

/// Regression: a `mark_failed` driven by the orphan-task sweep
/// during `enable_persistence` (`task_supervisor.rs:1164-1166`)
/// MUST reach the recovery callback. This pins the wiring order
/// the PR #1324 follow-up established: `set_on_failure_signal`
/// runs BEFORE `enable_persistence`, otherwise the orphan sweep's
/// `mark_failed` hits an `on_failure: None` slot and the recovery
/// turn for the resurrected task is silently dropped.
///
/// Reproducer: a single supervisor with an in-memory non-terminal
/// task plus a recorded synth-ack. Calling `enable_persistence`
/// AFTER both states are established sweeps the task into the
/// `Failed` runtime state and — because the ack IS recorded —
/// `notify_failure` lands on the "ack already recorded" arm,
/// which fires `invoke_failure_callback` synchronously inside
/// `mark_failed`. With the corrected wiring order (callback
/// before persistence), the recovery callback fires and the
/// orchestrator's queue gains exactly one continuation. With
/// the pre-fix order (callback after persistence), the callback
/// is `None` at the moment `mark_failed` runs and the failure
/// is silently dropped — `pending_continuation_count` stays at 0.
///
/// The test deliberately exercises only the live in-memory
/// orphan-sweep path. The persisted-ledger path (Phase 1 / Phase 2
/// across a supervisor drop) sweeps the task into the same
/// `Failed` state but lands on the stash arm of `notify_failure`
/// — the ack-set is not persisted, so a fresh supervisor sees no
/// ack on the replayed task. That stash-arm path is covered by
/// the unit tests in `task_supervisor::tests`; what this test
/// pins is the WIRING ORDER on a single supervisor.
#[tokio::test(flavor = "current_thread")]
async fn ws_turn_supervisor_orphan_sweep_failures_reach_recovery_callback() {
    // Use a profile_id distinct from MAIN_PROFILE_ID so this test
    // does not contaminate sibling tests that drain the
    // `default_agent_orchestrator()` static under the main profile.
    // (See the companion routes test for the rationale on why we
    // do not call `clear_default_agent_orchestrator_for_test()`.)
    let session_id = SessionKey("web:tester#l3-orphan".to_owned());
    let profile_id = "test-l3-orphan-isolate".to_owned();
    let temp = tempfile::tempdir().expect("tempdir");
    let ledger_path = temp.path().join("task_ledger.jsonl");

    // Build a per-turn registry exactly like the WS path.
    let parent = octos_agent::ToolRegistry::with_builtins(temp.path());
    let mut tool_registry = parent.snapshot_excluding(&[]);
    tool_registry.set_session_key(session_id.to_string());
    let task_supervisor = tool_registry.supervisor();

    // Pre-populate a non-terminal task + record its synth-ack. The
    // ack-set is in-memory only (not persisted), so this scenario
    // requires building both states on the same supervisor: a
    // fresh supervisor reloading from disk would not see the ack.
    let task_id = task_supervisor.register_with_input_and_cmid(
        "mofa_slides",
        "call-orphan-1",
        Some(&session_id.0),
        Some(serde_json::json!({"topic": "rust"})),
        Some("user-cmid-orphan".to_owned()),
    );
    task_supervisor.mark_synth_ack_emitted("call-orphan-1");
    task_supervisor.mark_running(&task_id);

    // Wire the failure callback BEFORE enable_persistence — the
    // PR #1324 follow-up wiring order. The callback enqueues
    // against the global orchestrator, same as production at
    // `run_standalone_turn`.
    let cb_session = session_id.clone();
    let cb_profile = profile_id.clone();
    task_supervisor.set_on_failure_signal(move |signal| {
        let _ = default_agent_orchestrator().enqueue_spawn_only_failure_continuation(
            &cb_session,
            &cb_profile,
            signal,
        );
    });

    // enable_persistence runs the orphan sweep over the in-memory
    // map. The `mark_running` task is non-terminal, so the sweep
    // `mark_failed`'s it. `notify_failure` finds the ack already
    // recorded (from the `mark_synth_ack_emitted` call above) and
    // takes the "ack already recorded" arm — which invokes
    // `invoke_failure_callback` synchronously inside
    // `mark_failed`. Pre-fix wiring (callback AFTER
    // enable_persistence) would observe `on_failure: None` here
    // and silently drop the recovery; the corrected order surfaces
    // it on the orchestrator queue.
    task_supervisor
        .enable_persistence(&ledger_path)
        .expect("enable_persistence on per-turn supervisor");

    let reaped = task_supervisor
        .get_task(&task_id)
        .expect("orphaned task must still be tracked after sweep");
    assert_eq!(reaped.status, octos_agent::TaskStatus::Failed);

    assert_eq!(
        default_agent_orchestrator()
            .pending_continuation_count_for_session_for_test(&session_id, &profile_id,),
        1,
        "orphan-sweep failure (ack-recorded arm) must reach the \
             recovery callback when `set_on_failure_signal` is wired \
             BEFORE `enable_persistence` (PR #1324 follow-up ordering)",
    );

    drop(tool_registry);
}

#[test]
fn coding_tool_status_distinguishes_registered_hidden_tools_from_missing_tools() {
    let temp = tempfile::tempdir().expect("tempdir");
    let mut registry = octos_agent::ToolRegistry::with_builtins(temp.path());
    registry.set_context_filter(vec!["read".into()]);

    let visible = model_visible_tool_names(Some(&registry));
    let registered = registered_tool_names(Some(&registry));
    assert!(!visible.iter().any(|name| name == "exec_command"));
    assert!(registered.iter().any(|name| name == "exec_command"));

    let visible_set: HashSet<&str> = visible.iter().map(String::as_str).collect();
    let disabled = registered
        .iter()
        .filter(|name| !visible_set.contains(name.as_str()))
        .cloned()
        .collect::<Vec<_>>();
    let visible_refs = visible.iter().map(String::as_str).collect::<Vec<_>>();
    let disabled_refs = disabled.iter().map(String::as_str).collect::<Vec<_>>();
    let payload = coding_tool_contract::tool_status_list_payload(
        coding_tool_contract::ToolStatusListContext {
            available_model_tools: &visible_refs,
            disabled_model_tools: &disabled_refs,
            ..coding_tool_contract::ToolStatusListContext::default_for_session("coding:test")
        },
    );
    let required = payload["coding_tool_contract"]["required_tools"]
        .as_array()
        .expect("required tools");
    let exec_command = required
        .iter()
        .find(|tool| tool["name"] == json!("exec_command"))
        .expect("exec_command status");

    assert_eq!(
        exec_command["status"],
        json!(coding_tool_contract::TOOL_STATUS_DISABLED_BY_POLICY)
    );
    assert_ne!(
        exec_command["status"],
        json!(coding_tool_contract::TOOL_STATUS_MISSING)
    );
}

