/// PART A + PART C — closing a peer BY NAME reaches the right peer, cancels its
/// PENDING `peer_send_input` injection (no durable leak), and leaves siblings
/// untouched.
#[test]
fn peer_close_by_name_cancels_pending_injection_for_right_peer() {
    use crate::autonomy::agent_orchestrator::PeerSendInputEnqueueOutcome;
    let orchestrator = default_agent_orchestrator();
    let profile_id = "test-peer-close-by-name";
    let owner = "test-peer-close-by-name:api:master";
    let tmp = tempfile::tempdir().unwrap();
    let peers = tmp.path().join("peers");
    let ws = tmp.path().join("ws");
    std::fs::create_dir_all(&ws).unwrap();

    let edison = stage_peer(
        &peers,
        &ws,
        "s",
        Some("Edison"),
        None,
        "b",
        false,
        None,
        None,
    )
    .unwrap();
    let tesla = stage_peer(
        &peers,
        &ws,
        "s",
        Some("Tesla"),
        None,
        "b",
        false,
        None,
        None,
    )
    .unwrap();
    assert_eq!(edison.slug, "edison");
    assert_eq!(tesla.slug, "tesla");
    std::fs::write(peers.join("edison").join("originator"), owner).unwrap();
    std::fs::write(peers.join("tesla").join("originator"), owner).unwrap();

    // Queue an injection to Edison — the pre-close leak scenario.
    let wire = SessionKey::with_profile_topic(profile_id, "api", "c1", "peer-edison");
    assert_eq!(
        orchestrator
            .enqueue_peer_send_input_continuation(&wire, profile_id, "edison", "occ-1", "resume"),
        PeerSendInputEnqueueOutcome::Queued
    );
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&wire, profile_id),
        1
    );

    // Close BY DISPLAY NAME (case-insensitive) → the RIGHT peer closes, its
    // pending injection is cancelled, and the sibling is untouched.
    let close = build_peer_close_callback(
        peers.clone(),
        owner.to_owned(),
        profile_id.to_owned(),
        Arc::new(UiProtocolContractStores::default()),
        Arc::new(|_event: PeerClosedEvent| {}),
        Arc::new(|_event: ApprovalCancelledEvent| {}),
    );
    let msg = close("EDISON".to_owned()).expect("close by name");
    assert!(msg.contains("edison"), "confirmation names the slug: {msg}");
    assert!(peer_is_closed(&peers, "edison"), "the named peer is closed");
    assert!(!peer_is_closed(&peers, "tesla"), "the sibling is untouched");
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&wire, profile_id),
        0,
        "peer_close cancels the peer's pending injection (no durable leak)"
    );
}

/// FIX 1 (security) — a SYMLINKED `peers/<slug>` entry is never resolved, read,
/// closed, or written through: `staged_peer_dir` inspects the link (not its
/// target), so I/O can't escape `peers/`.
#[cfg(unix)]
#[test]
fn symlinked_peer_entry_is_not_resolved_or_written() {
    let tmp = tempfile::tempdir().unwrap();
    let peers = tmp.path().join("peers");
    std::fs::create_dir_all(&peers).unwrap();
    // A hostile target OUTSIDE peers/, complete with brief/name/closed so it
    // WOULD resolve if the symlink were followed.
    let outside = tmp.path().join("outside");
    std::fs::create_dir_all(&outside).unwrap();
    std::fs::write(outside.join("brief.md"), "b").unwrap();
    std::fs::write(outside.join("name"), "Edison").unwrap();
    std::fs::write(outside.join("closed"), "x").unwrap();
    std::os::unix::fs::symlink(&outside, peers.join("edison")).unwrap();

    // Every access refuses the symlink.
    assert!(staged_peer_dir(&peers, "edison").is_none());
    assert_eq!(resolve_peer_name_to_slug(&peers, "Edison"), None);
    assert_eq!(resolve_peer_name_to_slug(&peers, "edison"), None);
    assert!(
        !peer_is_closed(&peers, "edison"),
        "a symlinked entry's `closed` is not followed"
    );
    assert!(
        read_peer_blackboard(&peers, None).is_empty(),
        "a symlinked entry is not a blackboard row"
    );
    // peer_close cannot resolve (hence cannot write a marker) through the link.
    let close = build_peer_close_callback(
        peers.clone(),
        "owner".to_owned(),
        "prof".to_owned(),
        Arc::new(UiProtocolContractStores::default()),
        Arc::new(|_event: PeerClosedEvent| {}),
        Arc::new(|_event: ApprovalCancelledEvent| {}),
    );
    let err = close("Edison".to_owned()).expect_err("symlinked peer must not resolve/close");
    assert!(err.contains("no peer named"), "reason: {err}");

    // A REAL staged peer beside the symlink is handled normally.
    let real = peers.join("tesla");
    std::fs::create_dir_all(&real).unwrap();
    std::fs::write(real.join("brief.md"), "b").unwrap();
    assert!(staged_peer_dir(&peers, "tesla").is_some());
    assert_eq!(
        resolve_peer_name_to_slug(&peers, "tesla").as_deref(),
        Some("tesla")
    );
}

/// FIX 2 (security) — an unsafe topic-derived slug (`peer-/tmp/x`, `peer-../x`,
/// a separator/NUL topic) is treated as a NON-peer session, so it never feeds
/// `Path::join` or the wire registry.
#[test]
fn unsafe_peer_topic_slug_is_treated_as_non_peer() {
    for topic in [
        "peer-/tmp/x",
        "peer-../x",
        "peer-a/b",
        "peer-a\0b",
        "peer-.",
    ] {
        let s = SessionKey::with_profile_topic("dev", "api", "tab", topic);
        assert!(
            peer_slug_and_profile(&s).is_none(),
            "{topic:?} must not parse as a peer session"
        );
        assert!(
            peer_target_is_current_wire(&s),
            "{topic:?} is a non-peer target (never gated)"
        );
    }
    // A safe peer topic still parses.
    let ok = SessionKey::with_profile_topic("dev", "api", "tab", "peer-edison");
    assert_eq!(peer_slug_and_profile(&ok), Some(("dev", "edison")));

    // register_peer_wire_session must NOT register a wire for an unsafe topic.
    let state = Arc::new(AppState::empty_for_tests());
    let bad = SessionKey::with_profile_topic("dev", "api", "tab", "peer-/tmp/x");
    register_peer_wire_session(&state, &bad);
    assert_eq!(
        peer_wire_registry().resolve(&peer_wire_key("dev", "/tmp/x")),
        None,
        "an unsafe peer topic must not register a wire key"
    );
}

/// A worktree peer's git state must live INSIDE its own workspace, so git
/// actually works there.
///
/// Regression guard for the bug that made worktree peers useless. They were
/// staged with `git worktree add`, whose `.git` is a FILE pointing at
/// `<repo>/.git/worktrees/<name>` — OUTSIDE the peer's sandboxed workspace. The
/// sandbox confines a peer to `peers/<slug>/wt`, so every git command failed:
///
/// ```text
/// fatal: not a git repository: .../work/.git/worktrees/wt      Exit code: 128
/// ```
///
/// The model then "recovered" by running `git init`, destroying the fence, and
/// the branch stayed at the seed commit — a worktree peer produced a branch and
/// never landed anything on it. Live-observed on BOTH peers of a two-peer run.
///
/// The old tests could not catch this: they asserted the fence was CREATED,
/// never that a peer could USE it. So this asserts the property the sandbox
/// actually needs — the RESOLVED git dir is contained in the peer's own
/// workspace — plus a real commit and a collection round-trip.
#[test]
fn peer_fence_git_dir_is_inside_the_peer_workspace() {
    fn git(dir: &std::path::Path, args: &[&str]) -> std::process::Output {
        std::process::Command::new("git")
            .arg("-C")
            .arg(dir)
            .args(args)
            .output()
            .unwrap()
    }

    let tmp = tempfile::tempdir().unwrap();
    let peers = tmp.path().join("peers");
    let repo = tmp.path().join("project");
    std::fs::create_dir_all(&repo).unwrap();
    assert!(git(&repo, &["init", "-q"]).status.success());
    assert!(
        git(&repo, &["config", "user.email", "t@t"])
            .status
            .success()
    );
    assert!(
        git(&repo, &["config", "user.name", "ymote"])
            .status
            .success()
    );
    std::fs::write(repo.join("seed.txt"), b"seed\n").unwrap();
    assert!(git(&repo, &["add", "-A"]).status.success());
    assert!(git(&repo, &["commit", "-q", "-m", "seed"]).status.success());

    let staged = stage_peer(
        &peers,
        &repo,
        "Fenced",
        None,
        None,
        "Own fence.",
        true,
        None,
        None,
    )
    .expect("staging");
    let cwd = &staged.cwd;

    // THE fix: `.git` is a real directory in the peer's workspace, not a file
    // redirecting outside it.
    assert!(
        cwd.join(".git").is_dir(),
        "the peer's .git must be a real directory inside its workspace, not a \
         worktree pointer file to the parent repo"
    );

    // The property the sandbox needs: the RESOLVED git dir is contained in the
    // peer's own workspace, so confining the peer to `cwd` cannot break git.
    let out = git(cwd, &["rev-parse", "--absolute-git-dir"]);
    assert!(out.status.success(), "git must work inside the peer fence");
    let git_dir = std::path::PathBuf::from(String::from_utf8_lossy(&out.stdout).trim().to_owned());
    let contained = std::fs::canonicalize(&git_dir)
        .unwrap_or_else(|_| git_dir.clone())
        .starts_with(std::fs::canonicalize(cwd).unwrap_or_else(|_| cwd.clone()));
    assert!(
        contained,
        "the peer's git dir must resolve INSIDE its workspace, got {}",
        git_dir.display()
    );

    // On its own fence branch...
    let head = git(cwd, &["rev-parse", "--abbrev-ref", "HEAD"]);
    assert_eq!(
        String::from_utf8_lossy(&head.stdout).trim(),
        "peer/fenced",
        "the peer must start on its own fence branch"
    );

    // ...and able to actually commit. A clone does NOT inherit the source's
    // LOCAL config, so this also covers the carried-over commit identity —
    // without it every peer commit fails on "unable to auto-detect email".
    std::fs::write(cwd.join("work.txt"), b"peer output\n").unwrap();
    assert!(git(cwd, &["add", "-A"]).status.success());
    let commit = git(cwd, &["commit", "-q", "-m", "peer deliverable"]);
    assert!(
        commit.status.success(),
        "a peer must be able to commit inside its fence: {}",
        String::from_utf8_lossy(&commit.stderr)
    );

    // The commit is NOT in the workspace repo yet — it lives in the peer's
    // clone until collection.
    assert!(
        !git(&repo, &["rev-parse", "--verify", "-q", "peer/fenced"])
            .status
            .success(),
        "the fence branch must not appear in the workspace before collection"
    );

    // Collection pulls it back, so the deliverable is visible from the workspace.
    collect_peer_branch(&peers.join(&staged.slug), &staged.slug);
    assert!(
        git(&repo, &["rev-parse", "--verify", "-q", "peer/fenced"])
            .status
            .success(),
        "collect_peer_branch must land the fence branch in the workspace repo"
    );
    let subject = git(&repo, &["log", "-1", "--format=%s", "peer/fenced"]);
    assert_eq!(
        String::from_utf8_lossy(&subject.stdout).trim(),
        "peer deliverable",
        "the collected branch must carry the peer's commit"
    );
}

/// Collecting a peer's fence must be idempotent and must not require a close.
///
/// `collect_peer_branch` originally ran ONLY on `peer_close`, so a peer that
/// simply finished — the common case — kept its deliverable stranded in its own
/// clone: committed, intact, and invisible from the workspace. A live soak showed
/// exactly that split, with the closed peer's branch landing and the un-closed
/// peer's not, despite both having committed. It now runs after every peer turn,
/// which means it must survive being called repeatedly.
#[test]
fn collecting_a_peer_fence_is_repeatable_and_tracks_new_commits() {
    fn git(dir: &std::path::Path, args: &[&str]) -> std::process::Output {
        std::process::Command::new("git")
            .arg("-C")
            .arg(dir)
            .args(args)
            .output()
            .unwrap()
    }

    let tmp = tempfile::tempdir().unwrap();
    let peers = tmp.path().join("peers");
    let repo = tmp.path().join("project");
    std::fs::create_dir_all(&repo).unwrap();
    assert!(git(&repo, &["init", "-q"]).status.success());
    assert!(
        git(&repo, &["config", "user.email", "t@t"])
            .status
            .success()
    );
    assert!(
        git(&repo, &["config", "user.name", "ymote"])
            .status
            .success()
    );
    assert!(
        git(&repo, &["commit", "--allow-empty", "-q", "-m", "seed"])
            .status
            .success()
    );

    let staged = stage_peer(
        &peers,
        &repo,
        "Turnwise",
        None,
        None,
        "Commit twice.",
        true,
        None,
        None,
    )
    .expect("staging");
    let dir = peers.join(&staged.slug);

    // Nothing committed yet: collecting must be a harmless no-op, not an error
    // and not a spurious branch.
    collect_peer_branch(&dir, &staged.slug);

    // Turn 1.
    std::fs::write(staged.cwd.join("a.txt"), b"one\n").unwrap();
    assert!(git(&staged.cwd, &["add", "-A"]).status.success());
    assert!(
        git(&staged.cwd, &["commit", "-q", "-m", "turn one"])
            .status
            .success()
    );
    collect_peer_branch(&dir, &staged.slug);
    let after_one = git(&repo, &["log", "-1", "--format=%s", "peer/turnwise"]);
    assert_eq!(
        String::from_utf8_lossy(&after_one.stdout).trim(),
        "turn one",
        "a peer's work must be visible in the workspace WITHOUT being closed"
    );

    // Turn 2 — the same collection must fast-forward, not fail on non-ff.
    std::fs::write(staged.cwd.join("b.txt"), b"two\n").unwrap();
    assert!(git(&staged.cwd, &["add", "-A"]).status.success());
    assert!(
        git(&staged.cwd, &["commit", "-q", "-m", "turn two"])
            .status
            .success()
    );
    collect_peer_branch(&dir, &staged.slug);
    let after_two = git(&repo, &["log", "-1", "--format=%s", "peer/turnwise"]);
    assert_eq!(
        String::from_utf8_lossy(&after_two.stdout).trim(),
        "turn two",
        "repeat collection must advance the branch to the peer's latest commit"
    );
}

/// A peer key with NO profile component is not addressable, and must keep
/// parsing as a non-peer session.
///
/// This is the shape of a real footgun: `peers_root` is per-profile and the wire
/// key is `{profile}:peer:{slug}`, so without a profile there is nothing to
/// address. `peer_slug_and_profile` therefore returns `None` — and all ~10
/// callers do `let Some(..) = .. else { return }`, which is right for "not a
/// peer" and silently wrong here. The peer runs, looks healthy, and its result
/// recording, blackboard writes, awaiting-input wake and fleet synthesis ALL
/// no-op, with nothing logged anywhere.
///
/// The RETURN value stays `None` (callers must keep treating it as a non-peer
/// session — that is the #436 fence). What changed is that the two
/// intended-a-peer rejections now `warn!`, because this is the only layer that
/// still knows WHY. This test pins the contract so the fence is not accidentally
/// relaxed into `Some` while making the diagnostics louder.
#[test]
fn peer_key_without_a_profile_is_not_addressable() {
    let no_profile = SessionKey::with_topic("api", "tab", "peer-edison");
    assert_eq!(
        peer_slug_and_profile(&no_profile),
        None,
        "a profile-less peer key has nothing to address and must not parse"
    );

    // The SAME topic WITH a profile parses — so the profile component, not the
    // topic, is what makes a peer addressable.
    let with_profile = SessionKey::with_profile_topic("dev", "api", "tab", "peer-edison");
    assert_eq!(
        peer_slug_and_profile(&with_profile),
        Some(("dev", "edison"))
    );

    // A genuinely non-peer topic is also None: the one case where silence is
    // correct, and which stays indistinguishable in the RETURN value on purpose.
    let not_a_peer = SessionKey::with_profile_topic("dev", "api", "tab", "coding");
    assert_eq!(peer_slug_and_profile(&not_a_peer), None);
}

/// FIX 5 — a pending injection to a CLOSED peer is RETIRED (cancelled +
/// tombstoned) by the drain-gate retire path, not left pending/stranded. This
/// exercises the exact decision (`peer_is_closed`) + action
/// (`cancel_peer_send_input_continuations_for_peer`) the global-drain gate wires.
#[test]
fn drain_retires_continuation_for_closed_peer_not_pending() {
    use crate::autonomy::agent_orchestrator::PeerSendInputEnqueueOutcome;
    let orchestrator = default_agent_orchestrator();
    let profile_id = "test-drain-retire-closed";
    let slug = "retire-peer";
    let tmp = tempfile::tempdir().unwrap();
    let peers = tmp.path().join("peers");
    std::fs::create_dir_all(peers.join(slug)).unwrap();
    std::fs::write(peers.join(slug).join("brief.md"), "b").unwrap();

    let wire = SessionKey::with_profile_topic(profile_id, "api", "c1", &format!("peer-{slug}"));
    assert_eq!(
        orchestrator.enqueue_peer_send_input_continuation(&wire, profile_id, slug, "occ-1", "go"),
        PeerSendInputEnqueueOutcome::Queued
    );
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&wire, profile_id),
        1
    );

    // The peer is closed → the gate detects it via `peer_is_closed` and RETIRES
    // the pending set instead of skipping (which would strand it).
    std::fs::write(peers.join(slug).join("closed"), "owner\n0\n").unwrap();
    assert!(peer_is_closed(&peers, slug), "closed marker detected");
    orchestrator.cancel_peer_send_input_continuations_for_peer(profile_id, slug);
    assert_eq!(
        orchestrator.pending_continuation_count_for_session_for_test(&wire, profile_id),
        0,
        "a closed peer's continuation is retired, not left pending"
    );
}

/// #436 hardening — the peer_list index caps inline rows and folds the
/// overflow into a trailing "… and N more" line.
#[test]
fn peer_list_caps_rows_and_summarizes_overflow() {
    fn row(slug: &str) -> PeerBlackboardRow {
        PeerBlackboardRow {
            slug: slug.to_owned(),
            name: slug.to_owned(),
            brief: String::new(),
            brief_truncated: false,
            result: None,
            result_truncated: false,
            result_updated_unix: None,
            has_worktree: false,
            closed: false,
            turn_history: None,
            model_lane: None,
        }
    }
    let over = PEER_LIST_MAX_ROWS + 5;
    let rows: Vec<_> = (0..over).map(|i| row(&format!("p{i:04}"))).collect();
    let text = compose_peer_list_text(&rows, &[], &Default::default());
    assert!(
        text.starts_with(&format!("peers ({over}):")),
        "header reports the true count: {:?}",
        text.lines().next()
    );
    let listed = text.lines().filter(|l| l.starts_with("- p")).count();
    assert_eq!(listed, PEER_LIST_MAX_ROWS, "inline rows are capped");
    assert!(
        text.contains("… and 5 more"),
        "overflow summarized: {text:?}"
    );

    // Under the cap: every row inline, no summary line.
    let few = compose_peer_list_text(&[row("only")], &[], &Default::default());
    assert!(few.contains("- only"), "{few}");
    assert!(
        !few.contains("more"),
        "no overflow line under the cap: {few}"
    );
}

/// #1801 v3 fan-in: the composed tool output is capped at 48KiB total,
/// truncated EVENLY across peers with a steering note — one verbose peer
/// cannot crowd out the rest, and every peer stays visible.
#[test]
fn peer_gather_callback_caps_total_output_evenly() {
    let tmp = tempfile::tempdir().unwrap();
    let peers_root = tmp.path().join("peers");
    for slug in ["p1", "p2", "p3"] {
        let dir = peers_root.join(slug);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("brief.md"), format!("Task {slug}.")).unwrap();
        std::fs::write(dir.join("result.md"), "r".repeat(30 * 1024)).unwrap();
    }
    let callback = build_peer_gather_callback(peers_root);
    let text = callback(None).unwrap();
    assert!(
        text.len() <= PEER_GATHER_TOOL_OUTPUT_CAP,
        "90KiB of results must compose under the {PEER_GATHER_TOOL_OUTPUT_CAP}-byte cap, got {}",
        text.len()
    );
    assert!(text.contains("truncated evenly"), "steering note present");
    for slug in ["p1", "p2", "p3"] {
        assert!(
            text.contains(&format!("## peer {slug} (done)")),
            "every peer stays visible: {slug}"
        );
    }
    assert_eq!(
        text.matches("[truncated]").count(),
        3,
        "each oversized peer is marked"
    );
}

