#[test]
fn no_leftover_steers_emits_nothing() {
    let (writer_tx, writer_rx) = std::sync::mpsc::sync_channel(4);
    let ws = WsConnection::new_stdio(writer_tx);
    let ledger = Arc::new(UiProtocolLedger::new(16));
    let session_id = SessionKey("local:steer-none".into());
    let turn_id = TurnId::new();
    let buffer: octos_agent::SharedSteerBuffer = Arc::new(octos_agent::SteerBuffer::default());

    let returned = settle_leftover_steers(
        &buffer,
        SteerReturnSink::Live {
            ws: &ws,
            ledger: &ledger,
        },
        &session_id,
        &turn_id,
        true,
    );

    assert_eq!(returned, 0);
    assert!(
        writer_rx.recv_timeout(Duration::from_millis(100)).is_err(),
        "an empty buffer must not produce an empty return frame"
    );
    assert!(ledgered_steer_dropped(&ledger, &session_id).is_empty());
    // Terminal payload shapes are untouched by this task: the legacy
    // `turn/error` frame still carries exactly its four fields.
    let error = UiNotification::TurnError(TurnErrorEvent {
        session_id: session_id.clone(),
        topic: None,
        turn_id: turn_id.clone(),
        code: "interrupted".into(),
        message: "turn interrupted by client".into(),
    })
    .into_rpc_notification()
    .expect("serialize turn/error");
    let keys: Vec<&str> = error
        .params
        .as_object()
        .unwrap()
        .keys()
        .map(String::as_str)
        .collect();
    assert_eq!(keys, vec!["session_id", "turn_id", "code", "message"]);
}

#[test]
fn leftover_steers_are_ledgered_even_when_connection_write_fails() {
    let (writer_tx, writer_rx) = std::sync::mpsc::sync_channel::<WsMessage>(1);
    let ws = WsConnection::new_stdio(writer_tx);
    // Simulate a dead stdio peer: the receiver is gone, so every send fails.
    drop(writer_rx);
    let ledger = Arc::new(UiProtocolLedger::new(16));
    let session_id = SessionKey("local:steer-dead-peer".into());
    let turn_id = TurnId::new();
    let buffer: octos_agent::SharedSteerBuffer = Arc::new(octos_agent::SteerBuffer::default());
    buffer.push("orphaned steer".into());

    let returned = settle_leftover_steers(
        &buffer,
        SteerReturnSink::Live {
            ws: &ws,
            ledger: &ledger,
        },
        &session_id,
        &turn_id,
        true,
    );

    assert_eq!(returned, 1);
    let ledgered = ledgered_steer_dropped(&ledger, &session_id);
    assert_eq!(ledgered.len(), 1, "text survives in the ledger for replay");
    assert_eq!(ledgered[0].inputs, vec!["orphaned steer"]);
}

/// task-return-unconsumed-steer-inputs (v2 ordering): once the turn flips to
/// Terminal, its accepted-but-undrained steers are returned as ONE
/// `turn/steer_dropped` BEFORE the terminal frame, on the same connection —
/// so a client may treat "terminal without a preceding steer_dropped naming
/// my steer" as "consumed". Drives `try_emit_terminal` directly (the wire-side
/// closure), like the #1332 test above.
#[tokio::test]
async fn steer_dropped_is_emitted_before_the_terminal_frame() {
    let (tx, mut rx) = tokio::sync::mpsc::channel::<axum::extract::ws::Message>(8);
    let ws = WsConnection::new(tx);
    let ledger = UiProtocolLedger::new(32);
    let session_id = SessionKey("local:steer-order".into());
    let turn_id = TurnId::new();
    let turn_state = TokioMutex::new(TurnState::Active);
    let buffer: octos_agent::SharedSteerBuffer = Arc::new(octos_agent::SteerBuffer::default());
    buffer.push("accepted but never drained".into());

    try_emit_terminal(
        &turn_state,
        TerminalReason::Interrupted,
        &ws,
        &ledger,
        &session_id,
        &turn_id,
        Some(("interrupted", "turn interrupted by client")),
        None,
        Some(&buffer),
    )
    .await;

    let mut methods = Vec::new();
    while let Ok(msg) = rx.try_recv() {
        if let axum::extract::ws::Message::Text(text) = msg {
            let frame: Value = serde_json::from_str(text.as_ref()).expect("json frame");
            if let Some(method) = frame.get("method").and_then(Value::as_str) {
                methods.push(method.to_string());
                if method == "turn/steer_dropped" {
                    assert_eq!(
                        frame["params"]["inputs"],
                        json!(["accepted but never drained"])
                    );
                    assert_eq!(frame["params"]["reason"], json!("interrupted"));
                }
            }
        }
    }
    let dropped_at = methods.iter().position(|m| m == "turn/steer_dropped");
    let terminal_at = methods.iter().position(|m| m == "turn/error");
    assert!(dropped_at.is_some(), "steer_dropped emitted: {methods:?}");
    assert!(terminal_at.is_some(), "terminal emitted: {methods:?}");
    assert!(
        dropped_at < terminal_at,
        "steer_dropped must precede the terminal: {methods:?}"
    );
    assert!(buffer.is_empty());
    assert!(matches!(
        *turn_state.lock().await,
        TurnState::Terminal(TerminalReason::Interrupted)
    ));

    // A second terminal attempt is a no-op (idempotent) and returns nothing more.
    try_emit_terminal(
        &turn_state,
        TerminalReason::Interrupted,
        &ws,
        &ledger,
        &session_id,
        &turn_id,
        Some(("interrupted", "turn interrupted by client")),
        None,
        Some(&buffer),
    )
    .await;
    assert!(
        rx.try_recv().is_err(),
        "no duplicate frames after the terminal"
    );
}

/// Once the state is Terminal, `turn/steer` can no longer be accepted for the
/// turn — the settlement above therefore saw the complete set of inputs.
#[tokio::test]
async fn steer_is_not_accepted_after_terminal_transition() {
    let turn_state = Arc::new(TokioMutex::new(TurnState::Active));
    let transition = transition_to_terminal(&turn_state, TerminalReason::Completed).await;
    assert!(transition.is_some());
    // The steer admission check reads the same state: Terminal → NoActiveTurn.
    let terminal = matches!(*turn_state.lock().await, TurnState::Terminal(_));
    assert!(terminal, "post-terminal steers fall back to a fresh turn");
}

/// The dropped-before-terminal guarantee is advertised as
/// `event.turn_steer_dropped.v1` — on by default for stdio, and honoured when
/// a ws client requests it — so a client can decide whether "terminal without
/// steer_dropped" means "consumed" (new server) or "unknown" (old server).
#[test]
fn turn_steer_dropped_feature_is_advertised_when_requested_and_by_stdio_default() {
    let stdio = ConnectionUiFeatures::stdio_defaults().negotiated_capabilities();
    assert!(
        stdio
            .supported_features
            .iter()
            .any(|f| f == UI_PROTOCOL_FEATURE_TURN_STEER_DROPPED_V1),
        "{:?}",
        stdio.supported_features
    );
    let ws = ConnectionUiFeatures::from_requested_feature_tokens(
        [UI_PROTOCOL_FEATURE_TURN_STEER_DROPPED_V1],
        false,
    )
    .negotiated_capabilities();
    assert!(
        ws.supported_features
            .iter()
            .any(|f| f == UI_PROTOCOL_FEATURE_TURN_STEER_DROPPED_V1)
    );
    let legacy = ConnectionUiFeatures::from_requested_feature_tokens(
        [UI_PROTOCOL_FEATURE_SESSION_HYDRATE_V1],
        false,
    )
    .negotiated_capabilities();
    assert!(
        !legacy
            .supported_features
            .iter()
            .any(|f| f == UI_PROTOCOL_FEATURE_TURN_STEER_DROPPED_V1),
        "not advertised unless requested"
    );
}

/// task-return-unconsumed-steer-inputs (review round 3, P0): the connection-
/// close abort path is a terminal outlet too. It must go through the same
/// gate, so the ledger a reconnecting client replays reads
/// `turn/steer_dropped` strictly BEFORE `turn/error(connection_closed)`.
#[tokio::test]
async fn connection_close_settles_steers_before_connection_closed_terminal() {
    let session_id = SessionKey("api:profile/local:closing".into());
    let turn_id = TurnId::new();
    let active_turns: SharedActiveTurns = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
    let connection_turns: SharedConnectionTurns = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
    let handle = tokio::spawn(async { std::future::pending::<()>().await });
    let buffer: octos_agent::SharedSteerBuffer = Arc::new(octos_agent::SteerBuffer::default());
    buffer.push("typed just before the socket died".into());
    let mut entry = test_active_turn(turn_id.clone(), handle.abort_handle());
    entry.steer = Some(buffer.clone());
    active_turns.lock().await.insert(session_id.clone(), entry);
    connection_turns
        .lock()
        .await
        .insert(session_id.clone(), turn_id.clone());

    let scopes = ScopePolicy::default();
    let ledger = UiProtocolLedger::new(16);
    let approvals = PendingApprovalStore::default();
    let user_questions = PendingQuestionStore::default();
    abort_connection_turns(
        &active_turns,
        &connection_turns,
        &scopes,
        &ledger,
        &approvals,
        &user_questions,
    )
    .await;

    let baseline = UiCursor {
        stream: session_id.0.clone(),
        seq: 0,
    };
    let replay = ledger.replay_after(&session_id, Some(&baseline)).unwrap();
    let kinds: Vec<String> = replay
        .iter()
        .filter_map(|e| match &e.event {
            UiProtocolLedgerEvent::Notification(UiNotification::TurnSteerDropped(d)) => {
                assert_eq!(d.inputs, vec!["typed just before the socket died"]);
                assert_eq!(d.reason, "interrupted");
                Some("turn/steer_dropped".to_string())
            }
            UiProtocolLedgerEvent::Notification(UiNotification::TurnError(err)) => {
                Some(format!("turn/error:{}", err.code))
            }
            _ => None,
        })
        .collect();
    let dropped_at = kinds.iter().position(|k| k == "turn/steer_dropped");
    let terminal_at = kinds
        .iter()
        .position(|k| k == "turn/error:connection_closed");
    assert!(dropped_at.is_some() && terminal_at.is_some(), "{kinds:?}");
    assert!(
        dropped_at < terminal_at,
        "replay order must be steer_dropped → terminal: {kinds:?}"
    );
    assert!(
        buffer.is_empty(),
        "the aborted turn's later safety-net drain finds nothing"
    );
    handle.abort();
}

// ---------------------------------------------------------------------------
// #2062 — session/open pushes an explicit NO-GOAL snapshot (goal-chip null
// state). "No goal" used to be represented by SILENCE on (re)open, so a client
// that cached a goal chip and reconnected after the goal was cleared elsewhere
// (a second connection, another process on the same data dir, or a serve
// restart that rebuilt the ledger) kept rendering the stale chip —
// absence-of-message is indistinguishable from message-not-yet-arrived. The
// open path now emits the SAME `session/goal/cleared` shape the explicit
// `session/goal/clear` RPC emits whenever no goal is bound for the resolved
// (session, profile), ephemeral (one client's catch-up state, not session
// history) and AFTER the ledger replay loop so a replayed stale
// `session/goal/updated` can never land behind it.
//
// CI: these run under the `session_open_goal` name filter in
// .github/workflows/ci.yml (test-octos-cli job) — the `api`-gated module is
// invisible to the unfeatured lib/integration steps (#2029).
// ---------------------------------------------------------------------------

/// Open `session_id` on a FRESH connection against the shared `state`/`ledger`
/// (modelling a reconnect) and return every `session/goal/cleared` params
/// payload pushed before the `session/opened` lifecycle notification (method
/// `session/open`) — the last frame the open path sends before handing the
/// connection to the live forwarder. A cleared emitted after that boundary
/// would be indistinguishable from a live event, so collection stops there.
async fn open_session_collecting_goal_cleared_frames(
    state: &Arc<AppState>,
    ledger: &Arc<UiProtocolLedger>,
    session_id: &SessionKey,
    request_id: &str,
) -> Vec<Value> {
    let (ws, mut rx) = ws_connection_for_test(64);
    let approvals = PendingApprovalStore::default();
    let questions = PendingQuestionStore::default();
    let forwarders: SharedLiveForwarders = Arc::new(tokio::sync::Mutex::new(HashMap::new()));
    let opened = handle_session_open(
        &ws,
        state,
        ledger,
        &approvals,
        &questions,
        &forwarders,
        None,
        ConnectionUiFeatures::stdio_defaults(),
        request_id.to_owned(),
        SessionOpenParams {
            session_id: session_id.clone(),
            topic: None,
            profile_id: None,
            cwd: None,
            sandbox: None,
            after: None,
        },
        false,
    )
    .await;
    assert!(opened, "session/open must succeed for {session_id}");
    let result = recv_rpc_json(&mut rx).await;
    assert_eq!(
        result["id"],
        json!(request_id),
        "first frame is the RPC result"
    );
    let mut cleared_frames = Vec::new();
    loop {
        let frame = recv_rpc_json(&mut rx).await;
        match frame["method"].as_str() {
            Some("session/goal/cleared") => cleared_frames.push(frame["params"].clone()),
            // The `session/opened` lifecycle notification closes the open
            // path's send sequence.
            Some("session/open") => break,
            _ => {}
        }
    }
    abort_live_forwarders(&forwarders, ledger).await;
    cleared_frames
}

/// #2062 RED→GREEN: a session that opens with NO goal bound must receive an
/// explicit `session/goal/cleared` null snapshot — silence is not a goal
/// state. Payload matches the explicit `session/goal/clear` RPC shape:
/// `cleared: true`, `goal: null`, a real (#1959) generation stamp, and the
/// wire session id the client keys the chip by.
#[tokio::test]
async fn session_open_goal_null_snapshot_emitted_when_no_goal_bound() {
    let temp = tempfile::tempdir().expect("tempdir");
    let state = state_with_sessions(temp.path());
    let ledger = Arc::new(UiProtocolLedger::new(16));
    let session_id = SessionKey("local:goal-null-snap-unbound".into());

    let cleared =
        open_session_collecting_goal_cleared_frames(&state, &ledger, &session_id, "open-a").await;

    assert_eq!(
        cleared.len(),
        1,
        "open with no goal bound must push exactly one explicit no-goal snapshot"
    );
    let event = &cleared[0];
    assert_eq!(event["session_id"], json!(session_id.0));
    assert_eq!(event["profile_id"], json!(MAIN_PROFILE_ID));
    assert_eq!(
        event["cleared"],
        json!(true),
        "the client nulls the chip only on cleared=true"
    );
    assert!(
        event["goal"].is_null(),
        "a null snapshot carries no goal record"
    );
    assert!(
        event["generation"].as_u64().unwrap_or(0) > 0,
        "#1959 — every goal chip event must carry a real generation stamp"
    );
}

/// #2062 inverse guard: a session that opens WITH a goal bound must NOT
/// receive a `session/goal/cleared` — a spurious cleared would blank a live
/// chip. The positive snapshot path (durable ledger replay + live charge
/// pushes) stays untouched.
#[tokio::test]
async fn session_open_goal_null_snapshot_suppressed_when_goal_bound() {
    use crate::autonomy::agent_orchestrator::{
        AgentOrchestrator as _, GoalSessionRequest, GoalSetRequest,
    };
    let temp = tempfile::tempdir().expect("tempdir");
    let state = state_with_sessions(temp.path());
    let ledger = Arc::new(UiProtocolLedger::new(16));
    let session_id = SessionKey("local:goal-null-snap-bound".into());
    default_agent_orchestrator()
        .set_goal(GoalSetRequest {
            session_id: session_id.clone(),
            profile_id: MAIN_PROFILE_ID.to_owned(),
            objective: "keep the chip painted across reconnect".into(),
            status: None,
            token_budget: None,
            transition_actor: None,
        })
        .expect("bind goal");

    let cleared =
        open_session_collecting_goal_cleared_frames(&state, &ledger, &session_id, "open-b").await;

    // Cleanup the process-global orchestrator BEFORE asserting so a failure
    // does not leak the goal into sibling tests.
    default_agent_orchestrator()
        .clear_goal(GoalSessionRequest {
            session_id: session_id.clone(),
            profile_id: MAIN_PROFILE_ID.to_owned(),
        })
        .expect("cleanup goal");

    assert!(
        cleared.is_empty(),
        "open with a bound goal must not push a cleared (it would blank a live chip): {cleared:?}"
    );
}

/// #2062 end-to-end shape from the issue: bind a goal, clear it "elsewhere"
/// (directly on the orchestrator — no ledger event, exactly like a second
/// connection or another process on the same data dir), then re-open. The
/// reopen must re-emit the cleared null snapshot (idempotent null), and its
/// #1959 generation must supersede the one from the first open so a stale
/// update can never outrank it.
#[tokio::test]
async fn session_open_goal_null_snapshot_reemitted_when_goal_cleared_elsewhere() {
    use crate::autonomy::agent_orchestrator::{
        AgentOrchestrator as _, GoalSessionRequest, GoalSetRequest,
    };
    let temp = tempfile::tempdir().expect("tempdir");
    let state = state_with_sessions(temp.path());
    let ledger = Arc::new(UiProtocolLedger::new(16));
    let session_id = SessionKey("local:goal-null-snap-reopen".into());

    // First open: nothing bound yet → explicit null snapshot.
    let first =
        open_session_collecting_goal_cleared_frames(&state, &ledger, &session_id, "open-c1").await;
    assert_eq!(
        first.len(),
        1,
        "first open with no goal pushes the null snapshot"
    );

    default_agent_orchestrator()
        .set_goal(GoalSetRequest {
            session_id: session_id.clone(),
            profile_id: MAIN_PROFILE_ID.to_owned(),
            objective: "cleared while you were away".into(),
            status: None,
            token_budget: None,
            transition_actor: None,
        })
        .expect("bind goal");

    // Reconnect while the goal is live → no cleared.
    let bound =
        open_session_collecting_goal_cleared_frames(&state, &ledger, &session_id, "open-c2").await;
    assert!(
        bound.is_empty(),
        "reopen with the goal live must stay positive: {bound:?}"
    );

    // The goal is cleared elsewhere: this connection's ledger never sees a
    // `session/goal/cleared`, so WITHOUT the open-path push the client's
    // cached chip would survive the next reconnect on silence alone.
    default_agent_orchestrator()
        .clear_goal(GoalSessionRequest {
            session_id: session_id.clone(),
            profile_id: MAIN_PROFILE_ID.to_owned(),
        })
        .expect("clear goal elsewhere");

    let reopened =
        open_session_collecting_goal_cleared_frames(&state, &ledger, &session_id, "open-c3").await;
    assert_eq!(
        reopened.len(),
        1,
        "reopen after an out-of-band clear must re-push the null snapshot"
    );
    let first_generation = first[0]["generation"].as_u64().expect("generation");
    let reopened_generation = reopened[0]["generation"].as_u64().expect("generation");
    assert!(
        reopened_generation > first_generation,
        "the re-emitted null snapshot must carry a newer generation \
         ({reopened_generation} vs {first_generation})"
    );
}
